const today = () => new Date().toISOString().split("T")[0];
const fmtFecha = (f) => { if(!f) return ""; const [y,m,d] = f.split("-"); return `${d}/${m}/${y}`; };
const generarNum = (prefijo, fecha, lista, campoNum) => {
  // Format: P010926-01, AV010926-01, ALB010926-01
  const d = fecha || today();
  const [y,m,day] = d.split("-");
  const base = prefijo + day + m + y.slice(2); // ej: P010926
  const delDia = lista.filter(x => x[campoNum] && x[campoNum].startsWith(base));
  const seq = String(delDia.length + 1).padStart(2, "0");
  return base + "-" + seq;
};
// Keep backward compat alias
const generarNumParte = (fecha, partes) => generarNum("P", fecha, partes, "numeroParte");
// Lista de nombres asignados/tecnicos: soporta el array nuevo (varios) y el string legacy (uno solo)
const listaNombres = (obj, campoArray, campoLegacy) => {
  const arr = obj && obj[campoArray];
  if (Array.isArray(arr) && arr.length) return arr;
  const legacy = obj && obj[campoLegacy];
  return legacy ? [legacy] : [];
};
const fmtNombres = (obj, campoArray, campoLegacy) => listaNombres(obj, campoArray, campoLegacy).join(" y ") || "—";
// Cadena de partes continuados: varios partes del mismo trabajo (visitas distintas), identificados
// por compartir "cadenaBase" (el numeroParte del parte original). Si un parte no tiene cadenaBase
// (datos antiguos o parte suelto) se usa su propio numeroParte como base.
const cadenaBaseDe = p => (p && (p.cadenaBase || p.numeroParte)) || ("id-" + (p && p.id));
const obtenerCadenaPartes = (partes, p) => (partes||[]).filter(x => cadenaBaseDe(x) === cadenaBaseDe(p)).sort((a,b)=>(a.numContinuacion||0)-(b.numContinuacion||0));

const diasDesde = (f) => { const d = Math.floor((new Date() - new Date(f)) / 86400000); return d < 0 ? 0 : d; };
const uid = () => Date.now() + Math.random();
// Código interno único de máquina, compartido entre Stock (máquinas en venta) y
// las máquinas de cada cliente — para que nunca se repita un código entre ambos.
const nextCodigoMaquina = (data) => {
  const nums = [];
  (data.stock||[]).forEach(m=>{ const n=parseInt((m.codigo||"").replace(/^MAQ-?/,""))||0; if(n) nums.push(n); });
  (data.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ const n=parseInt((m.codigo||"").replace(/^MAQ-?/,""))||0; if(n) nums.push(n); }));
  const max = nums.length ? Math.max(...nums) : 0;
  return "MAQ-"+String(max+1).padStart(4,"0");
};
// Asigna un código a las máquinas (stock y de clientes) que aún no lo tengan
// (registros creados antes de existir este campo). Devuelve el mismo objeto
// si no hay nada que rellenar, para no disparar guardados innecesarios.
const backfillCodigosMaquina = (d) => {
  const usados = new Set();
  (d.stock||[]).forEach(m=>{ if(m.codigo) usados.add(m.codigo); });
  (d.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ if(m.codigo) usados.add(m.codigo); }));
  let max = 0;
  usados.forEach(cod=>{ const n=parseInt((cod||"").replace(/^MAQ-?/,""))||0; if(n>max) max=n; });
  let changed = false;
  const sig = () => { max+=1; return "MAQ-"+String(max).padStart(4,"0"); };
  const stock = (d.stock||[]).map(m=>{ if(m.codigo) return m; changed=true; return {...m, codigo:sig()}; });
  const clientes = (d.clientes||[]).map(c=>{
    const maquinas = (c.maquinas||[]).map(m=>{ if(m.codigo) return m; changed=true; return {...m, codigo:sig()}; });
    return {...c, maquinas};
  });
  return changed ? {...d, stock, clientes} : d;
};
// Consumibles "clave" (colas muy recurrentes) que deben tener siempre su recuadro de
// stock en Inventario. Si una instalación ya tenía datos en el servidor sin estos
// artículos, los añadimos aquí (sin stock) en vez de obligar a crearlos a mano.
const CONSUMIBLES_CLAVE_NOMBRES = ["Cola cartucho natural","Cola cartucho transparente","Cola cartucho blanca","Saco cola natural","Saco cola transparente","Saco de cola blanca"];
const backfillConsumiblesClave = (d) => {
  const inv = d.inventario || [];
  const nums = inv.map(i=>parseInt((i.codigo||"").replace(/^INV-?/,""))||0);
  let max = nums.length ? Math.max(...nums) : 0;
  const sig = () => { max+=1; return "INV"+String(max).padStart(4,"0"); };
  let changed = false;
  let nuevoInv = inv.map(it => {
    if (CONSUMIBLES_CLAVE_NOMBRES.includes(it.nombre) && !it.consumibleClave) { changed = true; return {...it, consumibleClave:true}; }
    return it;
  });
  // IDs enteros consecutivos (nunca decimales: el resto de la app compara IDs con
  // === y un id con decimales podría truncarse al pasar por inputs/selects HTML).
  let nextId = Date.now();
  CONSUMIBLES_CLAVE_NOMBRES.forEach(nombre => {
    if (!nuevoInv.some(i => i.nombre === nombre)) {
      changed = true;
      nuevoInv = [...nuevoInv, {id:nextId++, codigo:sig(), nombre, descripcion:nombre, categoria:"Cola", unidad:"ud", stock:0, stockMin:5, precioCompra:0, precioVenta:0, consumibleClave:true}];
    }
  });
  return changed ? {...d, inventario: nuevoInv} : d;
};
// Geocodificación de direcciones de cliente usando Nominatim (OpenStreetMap), gratuito
// y sin API key. El resultado se cachea en el propio cliente (campos lat/lng) para no
// repetir la consulta — Nominatim limita el uso a ~1 petición/segundo.
const direccionCliente = (c) => [c.dirFiscal, c.cpFiscal, c.localidad, c.provinciaFiscal].filter(Boolean).join(", ");
// Para el mapa de máquinas siempre se prioriza la dirección de fábrica/instalación
// sobre la fiscal cuando existan ambas y sean distintas (las máquinas suelen estar
// en la nave/fábrica del cliente, no en su domicilio fiscal/administrativo). Además de
// la dirección completa, guarda el código postal y la provincia correspondientes a esa
// misma fuente (fábrica o fiscal) para poder usarlos como búsqueda de respaldo.
const datosMapaCliente = (c) => {
  const fab = [c.dirFabrica, c.cpFabrica, c.localidadFabrica, c.provinciaFabrica].filter(Boolean).join(", ");
  if (fab) return { dir: fab, cp: c.cpFabrica||"", provincia: c.provinciaFabrica||"" };
  return { dir: direccionCliente(c), cp: c.cpFiscal||"", provincia: c.provinciaFiscal||"" };
};
const direccionMapaCliente = (c) => datosMapaCliente(c).dir;
const geocodificarDireccion = async (direccion) => {
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(direccion+", España")}`;
    const res = await fetch(url, { headers: { "Accept":"application/json" } });
    const arr = await res.json();
    if (arr && arr[0]) return { lat: parseFloat(arr[0].lat), lng: parseFloat(arr[0].lon) };
  } catch(e) {}
  return null;
};
// Intenta localizar al cliente probando, en orden, la dirección completa, luego solo
// el código postal y, si tampoco hay resultado, solo la provincia — así un cliente con
// una dirección mal escrita o muy poco común al menos aparece (de forma aproximada)
// en el mapa en vez de no aparecer nunca. Devuelve también el nivel de precisión
// alcanzado para poder avisar en el mapa cuando la ubicación es solo aproximada.
const geocodificarConFallback = async (c) => {
  const { dir, cp, provincia } = datosMapaCliente(c);
  if (!dir) return null;
  let r = await geocodificarDireccion(dir);
  if (r) return { ...r, precision: "exacta" };
  if (cp) {
    await new Promise(res=>setTimeout(res,1100));
    r = await geocodificarDireccion(cp);
    if (r) return { ...r, precision: "cp" };
  }
  if (provincia) {
    await new Promise(res=>setTimeout(res,1100));
    r = await geocodificarDireccion(provincia);
    if (r) return { ...r, precision: "provincia" };
  }
  return null;
};
