const Input = ({ value, onChange, type="text", placeholder="" }) => <input type={type} value={value||""} onChange={onChange} placeholder={placeholder} style={inputStyle}/>;
const Select = ({ value, onChange, options }) => <select value={value} onChange={onChange} style={{...inputStyle}}>{options.map(o=><option key={o} value={o}>{o}</option>)}</select>;
// Selector de varios tecnicos a la vez (chips toggle) — para avisos/partes que realizan 2+ personas
const SelectorTecnicos = ({ value, onChange, usuarios }) => {
  const sel = Array.isArray(value) ? value : (value ? [value] : []);
  const toggle = (nombre) => onChange(sel.includes(nombre) ? sel.filter(n => n !== nombre) : [...sel, nombre]);
  return (
    <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
      {usuarios.map(u => {
        const on = sel.includes(u.nombre);
        return (
          <button key={u.id} type="button" onClick={() => toggle(u.nombre)}
            style={{padding:"6px 12px",borderRadius:20,border:"2px solid "+(on?"#3b82f6":"#2a3550"),background:on?"#3b82f615":"#0d1117",color:on?"#3b82f6":"#6b7a99",fontWeight:700,cursor:"pointer",fontSize:12,display:"flex",alignItems:"center",gap:5}}>
            {on && <Icon name="check" size={11} />}{u.nombre}
          </button>
        );
      })}
      {sel.length === 0 && <span style={{color:"#6b7a99",fontSize:11,alignSelf:"center"}}>Sin asignar</span>}
    </div>
  );
};
const AlbaranReceptorPicker = ({ clientes, value, email, direccion, onChange }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h); return () => document.removeEventListener("mousedown", h);
  }, []);
  const filtrados = value.trim().length === 0 ? clientes.slice(0, 8) :
    clientes.filter(c => { const q = value.toLowerCase(); return c.nombreEmpresa?.toLowerCase().includes(q) || c.nombreFiscal?.toLowerCase().includes(q) || c.localidad?.toLowerCase().includes(q); }).slice(0, 10);
  return (
    <div ref={ref} style={{position:"relative"}}>
      <div style={{position:"relative"}}>
        <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:"#6b7a99",pointerEvents:"none"}}><Icon name="search" size={13}/></span>
        <input value={value} onChange={e => { onChange(e.target.value, "", ""); setOpen(true); }} onFocus={() => setOpen(true)}
          placeholder="Buscar cliente existente o escribir nombre libre..."
          style={{...inputStyle,paddingLeft:30,width:"100%",boxSizing:"border-box"}} />
      </div>
      {open && (
        <div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:"#0d1117",border:"1px solid #2a3550",borderRadius:10,zIndex:300,boxShadow:"0 8px 32px rgba(0,0,0,.6)",overflow:"hidden",maxHeight:240,overflowY:"auto"}}>
          {filtrados.length === 0 && value.trim() && <div style={{padding:"8px 13px",color:"#6b7a99",fontSize:12}}>Sin coincidencias — se usará el nombre escrito</div>}
          {filtrados.map(c => {
            const ct = c.contactos?.find(x => x.principal) || c.contactos?.[0];
            return (
              <div key={c.id} onMouseDown={() => { onChange(c.nombreEmpresa, ct?.email || "", c.localidad || ""); setOpen(false); }}
                style={{padding:"9px 13px",cursor:"pointer",borderBottom:"1px solid #1a2236"}}
                onMouseEnter={e => e.currentTarget.style.background = "#151b2a"}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <div style={{color:"#f1f3f9",fontWeight:700,fontSize:13}}>{c.nombreEmpresa}</div>
                <div style={{color:"#6b7a99",fontSize:11}}>
                  {c.localidad && <span>{c.localidad}</span>}
                  {ct?.email && <span> · {ct.email}</span>}
                </div>
              </div>
            );
          })}
          {value.trim() && <div style={{padding:"8px 13px",color:"#0ea5e9",fontSize:12,fontWeight:600,borderTop:"1px solid #2a3550",background:"#0a0f1a"}}>Usar "{value}" como receptor</div>}
        </div>
      )}
    </div>
  );
};
const ClientePicker = ({ clientes, value, onChange, placeholder="Buscar cliente por nombre, fiscal o localidad..." }) => {
  const sel = clientes.find(c => c.id === parseInt(value)) || null;
  const [busq, setBusq] = useState(sel?.nombreEmpresa || "");
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const c = clientes.find(c => c.id === parseInt(value));
    if (c) setBusq(c.nombreEmpresa);
    else if (!value) setBusq("");
  }, [value]);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const filtrados = busq.trim().length === 0
    ? clientes.slice(0, 8)
    : clientes.filter(c => {
        const q = busq.toLowerCase();
        return c.nombreEmpresa?.toLowerCase().includes(q)
          || c.nombreFiscal?.toLowerCase().includes(q)
          || c.localidad?.toLowerCase().includes(q);
      }).slice(0, 10);
  const seleccionar = c => { setBusq(c.nombreEmpresa); onChange(c.id); setOpen(false); };
  const limpiar = e => { e.stopPropagation(); setBusq(""); onChange(""); setOpen(true); };
  return (
    <div ref={ref} style={{position:"relative"}}>
      <div style={{position:"relative"}}>
        <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:"#6b7a99",pointerEvents:"none"}}>
          <Icon name="search" size={13}/>
        </span>
        <input
          value={busq}
          onChange={e => { setBusq(e.target.value); onChange(""); setOpen(true); }}
          onFocus={() => setOpen(true)}
          placeholder={placeholder}
          style={{...inputStyle,paddingLeft:30,paddingRight:28,width:"100%",boxSizing:"border-box"}}
        />
        {(busq || value) && (
          <button onClick={limpiar} style={{position:"absolute",right:7,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:"#6b7a99",cursor:"pointer",fontSize:16,lineHeight:1,padding:0}}>×</button>
        )}
      </div>
      {/* Confirmación cliente seleccionado */}
      {sel && (
        <div style={{marginTop:4,background:"#10b98112",border:"1px solid #10b98133",borderRadius:7,padding:"5px 10px",display:"flex",alignItems:"center",gap:7}}>
          <span style={{color:"#10b981",fontSize:12}}>✓</span>
          <span style={{color:"#10b981",fontSize:12,fontWeight:700}}>{sel.nombreEmpresa}</span>
          {sel.nombreFiscal && <span style={{color:"#6b7a99",fontSize:11}}>· {sel.nombreFiscal}</span>}
          {sel.localidad && <span style={{color:"#6b7a99",fontSize:11}}>· {sel.localidad}</span>}
        </div>
      )}
      {/* Dropdown */}
      {open && (
        <div style={{position:"absolute",top:sel ? "calc(100% - 22px)" :"calc(100% + 4px)",left:0,right:0,background:"#0d1117",border:"1px solid #2a3550",borderRadius:10,zIndex:300,boxShadow:"0 8px 32px rgba(0,0,0,.6)",overflow:"hidden",maxHeight:260,overflowY:"auto"}}>
          {filtrados.length === 0 && (
            <div style={{padding:"10px 13px",color:"#6b7a99",fontSize:12}}>Sin resultados para "{busq}"</div>
          )}
          {filtrados.map(c => (
            <div key={c.id} onMouseDown={() => seleccionar(c)}
              style={{padding:"9px 13px",cursor:"pointer",borderBottom:"1px solid #1a2236",display:"flex",justifyContent:"space-between",alignItems:"center",background:c.id === parseInt(value) ? "#1a2236" :"transparent"}}
              onMouseEnter={e => e.currentTarget.style.background = "#151b2a"}
              onMouseLeave={e => e.currentTarget.style.background = c.id === parseInt(value) ? "#1a2236" : "transparent"}>
              <div>
                <div style={{color:"#f1f3f9",fontWeight:700,fontSize:13}}>{c.nombreEmpresa}</div>
                <div style={{color:"#6b7a99",fontSize:11}}>
                  {c.nombreFiscal && <span>{c.nombreFiscal}</span>}
                  {c.localidad && <span> · {c.localidad}</span>}
                </div>
              </div>
              {c.id === parseInt(value) && <span style={{color:"#10b981"}}>✓</span>}
            </div>
          ))}
          {filtrados.length > 0 && busq.trim().length > 0 && filtrados.length < clientes.filter(c=>{const q=busq.toLowerCase();return c.nombreEmpresa?.toLowerCase().includes(q)||c.nombreFiscal?.toLowerCase().includes(q)||c.localidad?.toLowerCase().includes(q);}).length && (
            <div style={{padding:"6px 13px",color:"#6b7a99",fontSize:11,fontStyle:"italic",background:"#0a0f1a"}}>Refina la búsqueda para ver más resultados</div>
          )}
        </div>
      )}
    </div>
  );
};
