const SignaturePad = ({ onSave, onClear, canvasRef }) => {
  const drawing = useRef(false);
  const lastPos = useRef(null);
  const getPos = (e, canvas) => {
    const rect = canvas.getBoundingClientRect();
    const src = e.touches ? e.touches[0] : e;
    return { x: (src.clientX - rect.left) * (canvas.width / rect.width),y: (src.clientY - rect.top) * (canvas.height / rect.height) };
  };
  const start = e => { e.preventDefault(); drawing.current = true; const c = canvasRef.current; lastPos.current = getPos(e, c); };
  const move = e => {
    e.preventDefault();
    if (!drawing.current) return;
    const c = canvasRef.current; const ctx = c.getContext("2d");
    const pos = getPos(e, c);
    ctx.beginPath(); ctx.moveTo(lastPos.current.x, lastPos.current.y);
    ctx.lineTo(pos.x, pos.y); ctx.strokeStyle = "#1e3a5f"; ctx.lineWidth = 2.5; ctx.lineCap = "round"; ctx.stroke();
    lastPos.current = pos;
  };
  const end = () => { drawing.current = false; onSave(); };
  const clear = () => { const c = canvasRef.current; c.getContext("2d").clearRect(0, 0, c.width, c.height); onClear(); };
  return (
    <div>
      <div style={{border:"2px dashed #2a3550",borderRadius:10,overflow:"hidden",background:"#f8faff",cursor:"crosshair",touchAction:"none"}}>
        <canvas ref={canvasRef} width={520} height={140} style={{display:"block",width:"100%",height:140}}
          onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
          onTouchStart={start} onTouchMove={move} onTouchEnd={end}/>
      </div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:5}}>
        <span style={{color:"#6b7a99",fontSize:11}}>Firma del cliente en el recuadro</span>
        <button onClick={clear} style={{background:"none",border:"1px solid #2a3550",borderRadius:6,padding:"3px 10px",color:"#8892a4",fontSize:12,cursor:"pointer"}}>Limpiar firma</button>
      </div>
    </div>
  );
};
