// ── INVENTARIO ──────────────────────────────────────────────
const Inventario = ({ data, setData, userActual, isMobile }) => {
  const puedeVerCompra = userActual?.rol==="manager"||userActual?.rol==="admin";
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({});
  const [busq, setBusq] = useState("");
  const [filtroCategoria, setFiltroCategoria] = useState("Todas");
  const [modalMovimiento, setModalMovimiento] = useState(null);
  const [cantMovimiento, setCantMovimiento] = useState("");
  const [modalHistorial, setModalHistorial] = useState(null); // artículo cuyo historial de entregas se está viendo
  const [fichaQR, setFichaQR] = useState(null); // producto abierto desde QR
  const [vistaQR, setVistaQR] = useState(false); // false | "elegir" | "manual" | "camara"
  const [qrInput, setQrInput] = useState("");
  const [camError, setCamError] = useState("");
  const videoRef = useRef(null);
  const canvasScanRef = useRef(null);
  const rafRef = useRef(null);
  const streamRef = useRef(null);
  const f = k => e => setForm(p => ({...p, [k]: e.target.value}));
  const handleFotoArt = e => {
    const file = e.target.files[0]; if (!file) return;
    const r = new FileReader();
    r.onload = ev => setForm(p => ({...p, foto: ev.target.result}));
    r.readAsDataURL(file);
  };

  const pararCamara = () => {
    if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t=>t.stop()); streamRef.current = null; }
  };

  const cerrarLectorQR = () => { pararCamara(); setVistaQR(false); setQrInput(""); setCamError(""); };

  const abrirFichaDesdeQR = (texto) => {
    const t = (texto||"").trim();
    if (!t) return;
    // QR generado por esta misma app (https://dominio/?articulo=CODIGO): buscamos el
    // artículo y abrimos su ficha dentro de la app, sin salir a una pestaña nueva.
    if (/^https?:\/\//i.test(t)) {
      try {
        const u = new URL(t);
        const cod = u.searchParams.get("articulo");
        if (cod) {
          const prod = data.inventario.find(i => i.codigo === cod);
          if (prod) { setFichaQR(prod); cerrarLectorQR(); return; }
          alert("No se ha encontrado ningún artículo con ese código.");
          cerrarLectorQR();
          return;
        }
      } catch(e) {}
      // Enlace externo que no es de esta app: lo abrimos en una pestaña nueva
      window.open(t, "_blank");
      cerrarLectorQR();
      return;
    }
    try {
      const datos = JSON.parse(t);
      if (datos.id || datos.codigo) {
        const prod = data.inventario.find(i => i.id === datos.id || i.codigo === datos.codigo);
        if (prod) { setFichaQR(prod); cerrarLectorQR(); return; }
        setFichaQR(datos); cerrarLectorQR();
        return;
      }
    } catch(e) {
      // El texto no es JSON, seguimos y lo tratamos como código de artículo
    }
    const prod = data.inventario.find(i => i.codigo === t);
    if (prod) { setFichaQR(prod); cerrarLectorQR(); }
    else alert("No se ha encontrado ningún artículo con ese código o QR.");
  };

  useEffect(() => {
    if (vistaQR !== "camara") return;
    let activo = true;
    setCamError("");
    navigator.mediaDevices?.getUserMedia({ video: { facingMode: "environment" } })
      .then(stream => {
        if (!activo) { stream.getTracks().forEach(t=>t.stop()); return; }
        streamRef.current = stream;
        if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play().catch(()=>{}); }
        const tick = () => {
          if (!activo) return;
          const video = videoRef.current, canvas = canvasScanRef.current;
          if (video && canvas && video.readyState === video.HAVE_ENOUGH_DATA && window.jsQR) {
            canvas.width = video.videoWidth; canvas.height = video.videoHeight;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const code = window.jsQR(img.data, img.width, img.height);
            if (code && code.data) { abrirFichaDesdeQR(code.data); return; }
          }
          rafRef.current = requestAnimationFrame(tick);
        };
        rafRef.current = requestAnimationFrame(tick);
      })
      .catch(err => setCamError("No se pudo acceder a la cámara: " + (err.message||err)));
    return () => { activo = false; pararCamara(); };
  }, [vistaQR]);

  const categorias = [...new Set(data.inventario.map(i => i.categoria).filter(Boolean))];

  const nextCodigo = () => {
    const nums = data.inventario.map(i => parseInt((i.codigo||"").replace(/^INV-?/,""))||0);
    const max = nums.length ? Math.max(...nums) : 0;
    return `INV${String(max+1).padStart(4,"0")}`;
  };

  const filtrados = data.inventario
    .filter(i => filtroCategoria === "Todas" || i.categoria === filtroCategoria)
    .filter(i => !busq || i.codigo?.toLowerCase().includes(busq.toLowerCase()) || i.nombre?.toLowerCase().includes(busq.toLowerCase()));

  const save = () => {
    const item = {...form, precioCompra: parseFloat(form.precioCompra)||0, precioVenta: parseFloat(form.precioVenta)||0, stock: parseInt(form.stock)||0,
      precioCompraProveedor1: form.precioCompraProveedor1!==undefined&&form.precioCompraProveedor1!==""?parseFloat(form.precioCompraProveedor1)||0:"",
      precioCompraProveedor2: form.precioCompraProveedor2!==undefined&&form.precioCompraProveedor2!==""?parseFloat(form.precioCompraProveedor2)||0:""};
    if (!item.id) setData(d => ({...d, inventario: [...d.inventario, {...item, id: Date.now()}]}));
    else setData(d => ({...d, inventario: d.inventario.map(i => i.id===item.id ? item : i)}));
    setModal(false);
  };

  const ajustarStock = (tipo) => {
    const cant = parseInt(cantMovimiento)||0;
    if (!cant) return;
    const registro = {id:Date.now()+Math.random(), fecha:today(), tipo, cantidad:cant, usuario:userActual?.nombre||""};
    setData(d => ({...d, inventario: d.inventario.map(i => i.id===modalMovimiento ? {...i, stock: tipo==="entrada" ? i.stock+cant : Math.max(0, i.stock-cant), historialAjustes:[registro, ...(i.historialAjustes||[])]} : i)}));
    setModalMovimiento(null); setCantMovimiento("");
  };

  const imprimirEtiqueta = (item) => {
    // El QR apunta a una página real de la app (https://dominio/?articulo=CODIGO),
    // así cualquier cámara de móvil puede abrirla directamente sin necesidad de iniciar sesión.
    // Nota: el precio de compra es información interna y nunca se incluye en la
    // etiqueta/ficha impresa ni en la página pública, ya que el QR puede ser escaneado por cualquiera.
    const urlArticulo = `${window.location.origin}/?articulo=${encodeURIComponent(item.codigo)}`;
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&ecc=M&data=${encodeURIComponent(urlArticulo)}`;

    // Ventana de impresión: empresa + nombre + codigo interno + codigos externos (sin proveedor) + QR
    const codigosExternos = [item.codigoExterno1, item.codigoExterno2].filter(Boolean);
    const w = window.open("","_blank","width=360,height=360");
    w.document.write(`<!DOCTYPE html><html><head><title>Etiqueta ${item.codigo}</title><style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;background:#fff}
.et{border:2px solid #000;padding:14px;width:230px;text-align:center}
.emp{font-size:7px;letter-spacing:1.5px;text-transform:uppercase;color:#555;margin-bottom:8px;font-weight:700}
.nom{font-size:12px;font-weight:700;color:#000;margin-bottom:6px;word-break:break-word}
.cod{font-size:22px;font-weight:900;letter-spacing:4px;color:#000;margin-bottom:6px}
.ext{font-size:9px;color:#333;margin-bottom:10px}
img{display:block;margin:0 auto}
@media print{body{min-height:0}}
</style></head><body>
<div class="et">
  <div class="emp">EUROPEA DE MAQUINARIA PMM SL</div>
  <div class="nom">${item.nombre||""}</div>
  <div class="cod">${item.codigo}</div>
  ${codigosExternos.length ? `<div class="ext">Cod. externo: ${codigosExternos.join(" · ")}</div>` : ""}
  <img src="${qrUrl}" width="190" height="190" alt="QR"/>
</div>
<script>
var img=document.querySelector("img");
img.onload=function(){setTimeout(function(){window.print();},300);};
img.onerror=function(){setTimeout(function(){window.print();},1500);};
<\/script></body></html>`);
    w.document.close();
  };

  const bajos = data.inventario.filter(i => !i.stock || i.stock <= 0);
  const totalCompra = data.inventario.reduce((s,i) => s+(i.precioCompra||0)*(i.stock||0), 0);
  const totalVenta  = data.inventario.reduce((s,i) => s+(i.precioVenta||0)*(i.stock||0), 0);

  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
        <div>
          <h2 style={{color:"#f1f3f9",fontWeight:800,fontSize:22,margin:0}}>Inventario</h2>
          <p style={{color:"#6b7a99",fontSize:13,margin:"3px 0 0"}}>Materiales y repuestos · Codigos · Etiquetas</p>
        </div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>setVistaQR("elegir")} style={{background:"#1a2236",color:"#a855f7",border:"1px solid #a855f755",borderRadius:9,padding:"9px 14px",fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:6,fontSize:13}}>
            <span style={{fontSize:16}}>📷</span>Leer QR
          </button>
          <button onClick={()=>{setForm({codigo:nextCodigo(),nombre:"",descripcion:"",categoria:"",unidad:"ud",stock:0,precioCompra:"",precioVenta:"",foto:null});setModal(true);}} style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:9,padding:"9px 16px",fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:6,fontSize:13}}>
            <Icon name="plus" size={14}/>Nuevo artículo
          </button>
        </div>
      </div>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:9,marginBottom:16}}>
        {[
          ["Artículos",data.inventario.length,"#a855f7"],
          ["Stock bajo",bajos.length,"#ef4444"],
          ...(puedeVerCompra ? [["Valor compra","EUR"+totalCompra.toFixed(0),"#3b82f6"]] : []),
          ["Valor venta","EUR"+totalVenta.toFixed(0),"#10b981"],
        ].map(([l,v,c])=>(
          <div key={l} style={{background:"#151b2a",border:`1px solid ${c}33`,borderRadius:11,padding:"12px 14px"}}>
            <div style={{color:c,fontWeight:800,fontSize:17,lineHeight:1}}>{v}</div>
            <div style={{color:"#6b7a99",fontSize:11,marginTop:3}}>{l}</div>
          </div>
        ))}
      </div>

      {/* Recuadros de stock de consumibles clave (colas muy recurrentes) */}
      {data.inventario.some(i=>i.consumibleClave) && (
        <div style={{marginBottom:16}}>
          <div style={{fontSize:11,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>Consumibles clave</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(170px,1fr))",gap:10}}>
            {data.inventario.filter(i=>i.consumibleClave).map(item=>{
              const sinStock = !item.stock || item.stock<=0;
              const bajo = !sinStock && item.stockMin && item.stock<=item.stockMin;
              const c = sinStock?"#ef4444":bajo?"#f59e0b":"#10b981";
              return (
                <div key={item.id} style={{background:"#151b2a",border:`1px solid ${c}44`,borderRadius:12,padding:"13px 15px"}}>
                  <div style={{color:"#f1f3f9",fontWeight:700,fontSize:13,marginBottom:6}}>{item.nombre}</div>
                  <div style={{display:"flex",alignItems:"baseline",gap:5,marginBottom:10}}>
                    <span style={{color:c,fontWeight:800,fontSize:24,lineHeight:1}}>{item.stock||0}</span>
                    <span style={{color:"#6b7a99",fontSize:12}}>{item.unidad||"ud"}</span>
                  </div>
                  <div style={{display:"flex",gap:6}}>
                    <button onClick={()=>{setModalMovimiento(item.id);setCantMovimiento("");}} style={{flex:1,background:"#10b98120",border:"1px solid #10b98133",borderRadius:7,padding:"6px 10px",cursor:"pointer",color:"#10b981",fontSize:12,fontWeight:700}}>+ Añadir unidades</button>
                    <button onClick={()=>setModalHistorial(item.id)} title="Historial de movimientos" style={{background:"#3b82f620",border:"1px solid #3b82f633",borderRadius:7,padding:"6px 9px",cursor:"pointer",color:"#3b82f6",fontSize:12,fontWeight:700}}>📋</button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Alerta stock bajo */}
      {bajos.length > 0 && (
        <div style={{background:"#ef444412",border:"1px solid #ef444433",borderRadius:10,padding:"10px 14px",marginBottom:14,display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:18}}>⚠️</span>
          <div>
            <div style={{color:"#ef4444",fontWeight:800,fontSize:12}}>{bajos.length} artículo{bajos.length>1?"s":""} con stock bajo o agotado</div>
            <div style={{color:"#6b7a99",fontSize:11}}>{bajos.map(i=>i.nombre).join(" · ")}</div>
          </div>
        </div>
      )}

      {/* Filtros */}
      <div style={{display:"flex",gap:6,marginBottom:12,alignItems:"center",flexWrap:"wrap"}}>
        <div style={{display:"flex",gap:3,flexWrap:"wrap"}}>
          {["Todas",...categorias].map(c=>(
            <button key={c} onClick={()=>setFiltroCategoria(c)} style={{background:filtroCategoria===c?"#a855f7":"#151b2a",color:filtroCategoria===c?"#fff":"#6b7a99",border:`1px solid ${filtroCategoria===c?"#a855f7":"#2a3550"}`,borderRadius:7,padding:"5px 11px",fontSize:12,fontWeight:600,cursor:"pointer"}}>{c}</button>
          ))}
        </div>
        <div style={{position:"relative",marginLeft:"auto"}}>
          <span style={{position:"absolute",left:8,top:"50%",transform:"translateY(-50%)",color:"#6b7a99"}}><Icon name="search" size={12}/></span>
          <input value={busq} onChange={e=>setBusq(e.target.value)} placeholder="Código o nombre..." style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:7,padding:"5px 9px 5px 27px",color:"#f1f3f9",fontSize:12,outline:"none",width:170}}/>
        </div>
      </div>

      {/* Tabla / lista */}
      {isMobile ? (
        <div style={{display:"flex",flexDirection:"column",gap:9}}>
          {filtrados.length===0 && <div style={{padding:"28px",textAlign:"center",color:"#6b7a99",background:"#151b2a",border:"1px solid #2a3550",borderRadius:12}}>Sin artículos</div>}
          {filtrados.map(item=>{
            const sinStock = !item.stock || item.stock <= 0;
            return (
              <div key={item.id} style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"12px 14px"}}>
                <div style={{display:"flex",gap:10,alignItems:"flex-start"}}>
                  {item.foto && <img src={item.foto} alt={item.nombre} style={{width:48,height:48,objectFit:"cover",borderRadius:8,border:"1px solid #2a3550",flexShrink:0}}/>}
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8}}>
                      <div style={{color:"#a855f7",fontWeight:700,fontSize:11,fontFamily:"monospace"}}>{item.codigo}</div>
                      <div style={{display:"flex",alignItems:"center",gap:4,flexShrink:0}}>
                        <span style={{color:sinStock?"#ef4444":"#10b981",fontWeight:800,fontSize:14}}>{item.stock}</span>
                        <span style={{color:"#6b7a99",fontSize:10}}>{item.unidad}</span>
                        {sinStock && <span style={{color:"#ef4444",fontSize:10}}>⚠️</span>}
                      </div>
                    </div>
                    <div style={{color:"#f1f3f9",fontWeight:600,fontSize:13,marginTop:2}}>{item.nombre}</div>
                    {item.descripcion && <div style={{color:"#6b7a99",fontSize:11,marginTop:1}}>{item.descripcion}</div>}
                    <div style={{display:"flex",gap:10,marginTop:6,flexWrap:"wrap"}}>
                      {puedeVerCompra && <div style={{color:"#6b7a99",fontSize:11}}>Compra: EUR{(item.precioCompra||0).toFixed(2)}</div>}
                      <div style={{color:"#10b981",fontWeight:700,fontSize:11}}>Venta: EUR{(item.precioVenta||0).toFixed(2)}</div>
                      {item.categoria && <div style={{color:"#9aa3b8",fontSize:11}}>{item.categoria}</div>}
                    </div>
                  </div>
                </div>
                <div style={{display:"flex",gap:6,marginTop:10,justifyContent:"flex-end"}}>
                  <button onClick={()=>{setModalMovimiento(item.id);setCantMovimiento("");}} style={{background:"#10b98120",border:"1px solid #10b98133",borderRadius:6,padding:"5px 9px",cursor:"pointer",color:"#10b981",fontSize:11,fontWeight:700}}>+/-</button>
                  <button onClick={()=>setModalHistorial(item.id)} style={{background:"#3b82f620",border:"1px solid #3b82f633",borderRadius:6,padding:"5px 9px",cursor:"pointer",color:"#3b82f6",fontSize:11,fontWeight:700}}>📋</button>
                  <button onClick={()=>imprimirEtiqueta(item)} style={{background:"#a855f720",border:"1px solid #a855f733",borderRadius:6,padding:"5px 9px",cursor:"pointer",color:"#a855f7",fontSize:11,fontWeight:700}}>🏷️</button>
                  <button onClick={()=>{setForm({...item});setModal(true);}} style={btnSm("#2a3550","#8892a4")}><Icon name="edit" size={12}/></button>
                  <button onClick={()=>setData(d=>({...d,inventario:d.inventario.filter(i=>i.id!==item.id)}))} style={btnSm("#3b1c1c","#dc2626")}><Icon name="trash" size={12}/></button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,overflow:"hidden"}}>
          <div style={{display:"grid",gridTemplateColumns:puedeVerCompra?"120px 1fr 90px 80px 80px 80px 120px":"120px 1fr 90px 80px 80px 120px",background:"#0a0f1a",padding:"9px 14px",gap:8}}>
            {(puedeVerCompra?["Código","Artículo","Stock","P. Compra","P. Venta","Categoría",""]:["Código","Artículo","Stock","P. Venta","Categoría",""]).map(h=>(
              <div key={h} style={{color:"#6b7a99",fontSize:10,fontWeight:700,textTransform:"uppercase"}}>{h}</div>
            ))}
          </div>
          {filtrados.length===0 && <div style={{padding:"28px",textAlign:"center",color:"#6b7a99"}}>Sin artículos</div>}
          {filtrados.map((item,idx)=>{
            const sinStock = !item.stock || item.stock <= 0;
            return (
              <div key={item.id} style={{display:"grid",gridTemplateColumns:puedeVerCompra?"120px 1fr 90px 80px 80px 80px 120px":"120px 1fr 90px 80px 80px 120px",padding:"10px 14px",gap:8,borderTop:"1px solid #1a2236",background:idx%2===0?"transparent":"#0d111720",alignItems:"center"}}>
                <div style={{color:"#a855f7",fontWeight:700,fontSize:12,fontFamily:"monospace"}}>{item.codigo}</div>
                <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0}}>
                  {item.foto && <img src={item.foto} alt={item.nombre} style={{width:32,height:32,objectFit:"cover",borderRadius:6,border:"1px solid #2a3550",flexShrink:0}}/>}
                  <div style={{minWidth:0}}>
                    <div style={{color:"#f1f3f9",fontWeight:600,fontSize:13}}>{item.nombre}</div>
                    {item.descripcion && <div style={{color:"#6b7a99",fontSize:11}}>{item.descripcion}</div>}
                  </div>
                </div>
                <div style={{display:"flex",alignItems:"center",gap:4}}>
                  <span style={{color:sinStock?"#ef4444":"#10b981",fontWeight:800,fontSize:14}}>{item.stock}</span>
                  <span style={{color:"#6b7a99",fontSize:10}}>{item.unidad}</span>
                  {sinStock && <span style={{color:"#ef4444",fontSize:10}}>⚠️</span>}
                </div>
                {puedeVerCompra && <div style={{color:"#6b7a99",fontSize:12}}>EUR{(item.precioCompra||0).toFixed(2)}</div>}
                <div style={{color:"#10b981",fontWeight:700,fontSize:12}}>EUR{(item.precioVenta||0).toFixed(2)}</div>
                <div style={{color:"#9aa3b8",fontSize:11}}>{item.categoria}</div>
                <div style={{display:"flex",gap:3}}>
                  <button onClick={()=>{setModalMovimiento(item.id);setCantMovimiento("");}} style={{background:"#10b98120",border:"1px solid #10b98133",borderRadius:6,padding:"4px 7px",cursor:"pointer",color:"#10b981",fontSize:10,fontWeight:700}}>+/-</button>
                  <button onClick={()=>setModalHistorial(item.id)} style={{background:"#3b82f620",border:"1px solid #3b82f633",borderRadius:6,padding:"4px 7px",cursor:"pointer",color:"#3b82f6",fontSize:10,fontWeight:700}}>📋</button>
                  <button onClick={()=>imprimirEtiqueta(item)} style={{background:"#a855f720",border:"1px solid #a855f733",borderRadius:6,padding:"4px 7px",cursor:"pointer",color:"#a855f7",fontSize:10,fontWeight:700}}>🏷️</button>
                  <button onClick={()=>{setForm({...item});setModal(true);}} style={btnSm("#2a3550","#8892a4")}><Icon name="edit" size={11}/></button>
                  <button onClick={()=>setData(d=>({...d,inventario:d.inventario.filter(i=>i.id!==item.id)}))} style={btnSm("#3b1c1c","#dc2626")}><Icon name="trash" size={11}/></button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal entrada/salida stock */}
      {modalMovimiento && (()=>{
        const item = data.inventario.find(i=>i.id===modalMovimiento);
        if (!item) return null;
        return (
          <Modal title={`Ajustar stock — ${item.nombre}`} onClose={()=>setModalMovimiento(null)}>
            <div style={{background:"#0d1117",borderRadius:10,padding:"12px 14px",marginBottom:14,display:"flex",justifyContent:"space-between"}}>
              <span style={{color:"#6b7a99",fontSize:13}}>Stock actual</span>
              <span style={{color:"#f1f3f9",fontWeight:800,fontSize:18}}>{item.stock} {item.unidad}</span>
            </div>
            <Field label="Cantidad"><input type="number" value={cantMovimiento} onChange={e=>setCantMovimiento(e.target.value)} min="1" placeholder="Unidades" style={{...inputStyle}}/></Field>
            <div style={{display:"flex",gap:9,justifyContent:"flex-end",marginTop:4}}>
              <button onClick={()=>setModalMovimiento(null)} style={btnOutline}>Cancelar</button>
              <button onClick={()=>ajustarStock("salida")} style={{...btnPrimary,background:"#ef4444"}}>- Salida</button>
              <button onClick={()=>ajustarStock("entrada")} style={{...btnPrimary,background:"#10b981"}}>+ Entrada</button>
            </div>
          </Modal>
        );
      })()}

      {/* Modal historial de movimientos: entradas manuales + salidas a clientes (partes/albaranes) */}
      {modalHistorial && (()=>{
        const item = data.inventario.find(i=>i.id===modalHistorial);
        if (!item) return null;
        // Unificamos dos fuentes en una sola línea de tiempo: las salidas a cliente
        // (historialEntregas, generadas desde Partes/Albaranes) y los ajustes manuales
        // de entrada/salida (historialAjustes, generados desde el botón "Añadir unidades").
        const entregas = (item.historialEntregas||[]).map(h => ({
          id: h.id, fecha: h.fecha, tipo: "salida",
          detalle: h.clienteNombre, doc: h.numeroParte || h.numeroAlbaran || "—",
          cantidad: parseFloat(h.cantidad)||0,
        }));
        const ajustes = (item.historialAjustes||[]).map(h => ({
          id: h.id, fecha: h.fecha, tipo: h.tipo,
          detalle: h.tipo==="entrada" ? "Entrada manual" : "Salida manual", doc: h.usuario || "—",
          cantidad: parseFloat(h.cantidad)||0,
        }));
        const historial = [...entregas, ...ajustes].sort((a,b)=>(b.fecha||"").localeCompare(a.fecha||""));
        return (
          <Modal title={`Historial de movimientos — ${item.nombre}`} onClose={()=>setModalHistorial(null)}>
            <div style={{background:"#0d1117",borderRadius:10,padding:"10px 14px",marginBottom:14,display:"flex",justifyContent:"space-between"}}>
              <span style={{color:"#6b7a99",fontSize:12}}>Código interno</span>
              <span style={{color:"#a855f7",fontWeight:700,fontSize:13,fontFamily:"monospace"}}>{item.codigo}</span>
            </div>
            {historial.length===0 ? (
              <div style={{color:"#6b7a99",fontSize:12,fontStyle:"italic",textAlign:"center",padding:"14px 0"}}>Este artículo aún no registra entradas ni salidas.</div>
            ) : (
              <div style={{background:"#0d1117",borderRadius:8,border:"1px solid #2a3550",overflow:"hidden"}}>
                <div style={{display:"grid",gridTemplateColumns:"80px 1fr 90px 60px",padding:"5px 10px",background:"#0a0f1a"}}>
                  {["Fecha","Detalle","Doc./User","Cant."].map(h=><div key={h} style={{color:"#6b7a99",fontSize:10,fontWeight:700,textTransform:"uppercase"}}>{h}</div>)}
                </div>
                {historial.map(h=>(
                  <div key={h.id} style={{display:"grid",gridTemplateColumns:"80px 1fr 90px 60px",padding:"7px 10px",borderTop:"1px solid #1a2236",alignItems:"center"}}>
                    <span style={{color:"#6b7a99",fontSize:11}}>{fmtFecha(h.fecha)}</span>
                    <span style={{color:"#f1f3f9",fontSize:12,fontWeight:600}}>{h.detalle}</span>
                    <span style={{color:"#0ea5e9",fontSize:11,fontWeight:700}}>{h.doc}</span>
                    <span style={{color:h.tipo==="entrada"?"#10b981":"#ef4444",fontWeight:700,fontSize:12,textAlign:"center"}}>{h.tipo==="entrada"?"+":"-"}{h.cantidad}</span>
                  </div>
                ))}
              </div>
            )}
            <div style={{display:"flex",justifyContent:"flex-end",marginTop:14}}>
              <button onClick={()=>setModalHistorial(null)} style={btnOutline}>Cerrar</button>
            </div>
          </Modal>
        );
      })()}

      {/* Modal nuevo/editar artículo */}
      {modal && (
        <Modal title={form.id?"Editar artículo":"Nuevo artículo"} onClose={()=>setModal(false)} wide>
          <div style={{background:"#a855f712",border:"1px solid #a855f733",borderRadius:8,padding:"8px 12px",marginBottom:12,display:"flex",alignItems:"center",gap:8}}>
            <span style={{color:"#a855f7",fontWeight:800,fontSize:14}}>{form.codigo}</span>
            <span style={{color:"#6b7a99",fontSize:12}}>— Código asignado automáticamente</span>
          </div>
          <Field label="Foto del artículo">
            <div style={{display:"flex",gap:10,alignItems:"center"}}>
              {form.foto && <img src={form.foto} alt="preview" style={{width:64,height:64,objectFit:"cover",borderRadius:8,border:"1px solid #2a3550"}}/>}
              <label style={{background:"#2a3550",color:"#9aa3b8",border:"1px solid #3a4560",borderRadius:8,padding:"7px 13px",cursor:"pointer",fontSize:13,display:"flex",alignItems:"center",gap:5,fontWeight:600}}>
                <Icon name="image" size={13}/>{form.foto?"Cambiar foto":"Subir foto"}
                <input type="file" accept="image/*" onChange={handleFotoArt} style={{display:"none"}}/>
              </label>
              {form.foto && <button onClick={()=>setForm(p=>({...p,foto:null}))} style={{...btnSm("#3b1c1c","#dc2626"),fontSize:12}}>Quitar</button>}
            </div>
          </Field>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(200px,100%),1fr))",gap:11}}>
            <Field label="Nombre del artículo"><Input value={form.nombre||""} onChange={f("nombre")} placeholder="Ej: Rodamiento 6205 2RS"/></Field>
            <Field label="Categoría"><Input value={form.categoria||""} onChange={f("categoria")} placeholder="Ej: Rodamientos, Correas..."/></Field>
            <Field label="Ubicación"><Input value={form.ubicacion||""} onChange={f("ubicacion")} placeholder="Ej: Taller, Sala de recambios, Despacho, Oficina Jose..."/></Field>
          </div>
          <Field label="Descripción"><Input value={form.descripcion||""} onChange={f("descripcion")} placeholder="Descripción detallada del artículo"/></Field>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(150px,100%),1fr))",gap:11}}>
            <Field label="Unidad"><Input value={form.unidad||"ud"} onChange={f("unidad")} placeholder="ud, m, L, kg..."/></Field>
            <Field label="Unidades"><Input type="number" value={form.stock||""} onChange={f("stock")} placeholder="0"/></Field>
            {puedeVerCompra && <Field label="Precio compra EUR"><Input type="number" value={form.precioCompra||""} onChange={f("precioCompra")}/></Field>}
            <Field label="Precio venta EUR"><Input type="number" value={form.precioVenta||""} onChange={f("precioVenta")}/></Field>
          </div>
          {puedeVerCompra && (
            <>
              <div style={{background:"#0d1117",borderRadius:10,padding:"12px 14px",marginTop:4}}>
                <div style={{fontSize:11,fontWeight:700,color:"#3b82f6",textTransform:"uppercase",letterSpacing:".5px",marginBottom:8}}>Proveedor externo 1 (compra alternativa)</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(160px,100%),1fr))",gap:9}}>
                  <Field label="Código externo 1"><Input value={form.codigoExterno1||""} onChange={f("codigoExterno1")} placeholder="Código en ese proveedor"/></Field>
                  <Field label="Proveedor externo 1"><Input value={form.proveedorExterno1||""} onChange={f("proveedorExterno1")} placeholder="Nombre del proveedor"/></Field>
                  <Field label="Precio compra proveedor 1 EUR">
                    <Input type="number" value={form.precioCompraProveedor1||""} onChange={e=>setForm(p=>({...p,precioCompraProveedor1:e.target.value,...(e.target.value&&!p.fechaPrecioProveedor1?{fechaPrecioProveedor1:today()}:{})}))}/>
                  </Field>
                  <Field label="Fecha del precio"><Input type="date" value={form.fechaPrecioProveedor1||""} onChange={f("fechaPrecioProveedor1")}/></Field>
                </div>
              </div>
              <div style={{background:"#0d1117",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:11,fontWeight:700,color:"#f59e0b",textTransform:"uppercase",letterSpacing:".5px",marginBottom:8}}>Proveedor externo 2 (compra alternativa)</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(160px,100%),1fr))",gap:9}}>
                  <Field label="Código externo 2"><Input value={form.codigoExterno2||""} onChange={f("codigoExterno2")} placeholder="Código en ese proveedor"/></Field>
                  <Field label="Proveedor externo 2"><Input value={form.proveedorExterno2||""} onChange={f("proveedorExterno2")} placeholder="Nombre del proveedor"/></Field>
                  <Field label="Precio compra proveedor 2 EUR">
                    <Input type="number" value={form.precioCompraProveedor2||""} onChange={e=>setForm(p=>({...p,precioCompraProveedor2:e.target.value,...(e.target.value&&!p.fechaPrecioProveedor2?{fechaPrecioProveedor2:today()}:{})}))}/>
                  </Field>
                  <Field label="Fecha del precio"><Input type="date" value={form.fechaPrecioProveedor2||""} onChange={f("fechaPrecioProveedor2")}/></Field>
                </div>
              </div>
            </>
          )}
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={()=>setModal(false)} style={btnOutline}>Cancelar</button>
            <button onClick={save} style={{...btnPrimary,background:"#a855f7"}}>{form.id?"Guardar":"Crear artículo"}</button>
          </div>
        </Modal>
      )}

      {/* Modal Lector QR — elegir método */}
      {vistaQR === "elegir" && (
        <Modal title="Leer QR — Inventario" onClose={cerrarLectorQR}>
          <div style={{color:"#9aa3b8",fontSize:13,marginBottom:16}}>¿Cómo quieres identificar el artículo?</div>
          <div style={{display:"flex",flexDirection:"column",gap:10}}>
            <button onClick={()=>setVistaQR("camara")} style={{background:"#151b2a",border:"1px solid #a855f755",borderRadius:10,padding:"14px 16px",color:"#f1f3f9",fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:12,fontSize:14,textAlign:"left"}}>
              <span style={{fontSize:24}}>📷</span>
              <span>Abrir cámara<div style={{color:"#6b7a99",fontSize:11,fontWeight:400,marginTop:2}}>Enfoca el QR del artículo y se abrirá su ficha</div></span>
            </button>
            <button onClick={()=>setVistaQR("manual")} style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"14px 16px",color:"#f1f3f9",fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:12,fontSize:14,textAlign:"left"}}>
              <span style={{fontSize:24}}>⌨️</span>
              <span>Introducir código manualmente<div style={{color:"#6b7a99",fontSize:11,fontWeight:400,marginTop:2}}>Escribe el código o usa un lector USB/Bluetooth</div></span>
            </button>
          </div>
          <div style={{display:"flex",justifyContent:"flex-end",marginTop:16}}>
            <button onClick={cerrarLectorQR} style={btnOutline}>Cancelar</button>
          </div>
        </Modal>
      )}

      {/* Modal Lector QR — manual */}
      {vistaQR === "manual" && (
        <Modal title="Introducir código — Inventario" onClose={cerrarLectorQR}>
          <div style={{background:"#0d1117",borderRadius:10,padding:"14px",marginBottom:14,textAlign:"center"}}>
            <div style={{fontSize:48,marginBottom:8}}>⌨️</div>
            <div style={{color:"#9aa3b8",fontSize:13,marginBottom:16}}>Pega aquí el contenido del QR o escanéalo con un lector USB/Bluetooth</div>
            <textarea
              autoFocus
              value={qrInput}
              onChange={e=>setQrInput(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();if(qrInput.trim())abrirFichaDesdeQR(qrInput.trim());}}}
              placeholder="El lector QR escribirá aquí automáticamente..."
              style={{width:"100%",background:"#151b2a",border:"1px solid #a855f755",borderRadius:8,padding:"10px 12px",color:"#f1f3f9",fontSize:13,resize:"vertical",minHeight:80,outline:"none",boxSizing:"border-box"}}
            />
            <div style={{color:"#6b7a99",fontSize:11,marginTop:6}}>También puedes escribir el código del artículo (ej: INV0001) y pulsar Enter</div>
          </div>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={()=>setVistaQR("elegir")} style={btnOutline}>Atrás</button>
            <button onClick={()=>{if(qrInput.trim())abrirFichaDesdeQR(qrInput.trim());}} style={{...btnPrimary,background:"#a855f7"}}>Abrir ficha</button>
          </div>
        </Modal>
      )}

      {/* Modal Lector QR — cámara */}
      {vistaQR === "camara" && (
        <Modal title="Escanear QR — Inventario" onClose={cerrarLectorQR}>
          <div style={{background:"#000",borderRadius:10,overflow:"hidden",marginBottom:14,position:"relative",minHeight:240,display:"flex",alignItems:"center",justifyContent:"center"}}>
            {camError ? (
              <div style={{color:"#ef4444",fontSize:13,padding:20,textAlign:"center"}}>{camError}</div>
            ) : (
              <video ref={videoRef} autoPlay muted playsInline style={{width:"100%",display:"block"}}/>
            )}
            <canvas ref={canvasScanRef} style={{display:"none"}}/>
          </div>
          <div style={{color:"#6b7a99",fontSize:11,marginBottom:14,textAlign:"center"}}>Enfoca el QR del artículo con la cámara; se abrirá automáticamente</div>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={()=>setVistaQR("elegir")} style={btnOutline}>Atrás</button>
            <button onClick={()=>setVistaQR("manual")} style={btnOutline}>Introducir manualmente</button>
          </div>
        </Modal>
      )}

      {/* Modal Ficha de producto (abierta desde QR) */}
      {fichaQR && (()=>{
        const item = data.inventario.find(i=>i.id===fichaQR.id) || fichaQR;
        const urlArticulo = `${window.location.origin}/?articulo=${encodeURIComponent(item.codigo)}`;
        const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=140x140&data=${encodeURIComponent(urlArticulo)}`;
        return (
          <Modal title={`Ficha: ${item.codigo} — ${item.nombre}`} onClose={()=>setFichaQR(null)} wide>
            <div style={{display:"grid",gridTemplateColumns:"1fr auto",gap:20,alignItems:"start"}}>
              <div>
                {item.foto && <img src={item.foto} alt={item.nombre} style={{width:"100%",maxHeight:160,objectFit:"cover",borderRadius:8,border:"1px solid #2a3550",marginBottom:10}}/>}
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:10}}>
                  {[
                    ["Código",item.codigo,"#a855f7"],
                    ["Nombre",item.nombre,"#f1f3f9"],
                    ["Categoría",item.categoria||"—","#9aa3b8"],
                    ["Ubicación",item.ubicacion||"—","#9aa3b8"],
                    ["Unidad",item.unidad||"ud","#9aa3b8"],
                    ["Stock actual",`${item.stock} ${item.unidad||"ud"}`,item.stock<=0?"#ef4444":"#10b981"],
                    ["Precio venta",`EUR ${(item.precioVenta||0).toFixed(2)}`,"#10b981"],
                    ...(puedeVerCompra ? [["Precio compra",`EUR ${(item.precioCompra||0).toFixed(2)}`,"#6b7a99"]] : []),
                  ].map(([lbl,val,col])=>(
                    <div key={lbl} style={{background:"#0d1117",borderRadius:8,padding:"10px 12px"}}>
                      <div style={{color:"#6b7a99",fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:4}}>{lbl}</div>
                      <div style={{color:col,fontWeight:700,fontSize:14}}>{val}</div>
                    </div>
                  ))}
                </div>
                {item.descripcion && (
                  <div style={{background:"#0d1117",borderRadius:8,padding:"10px 12px",marginBottom:10}}>
                    <div style={{color:"#6b7a99",fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:4}}>Descripción</div>
                    <div style={{color:"#9aa3b8",fontSize:13}}>{item.descripcion}</div>
                  </div>
                )}
              </div>
              <div style={{textAlign:"center",flexShrink:0}}>
                <img src={qrUrl} width="140" height="140" style={{border:"2px solid #2a3550",borderRadius:8,display:"block"}} alt="QR"/>
                <div style={{color:"#6b7a99",fontSize:9,marginTop:6}}>QR del producto</div>
                <button onClick={()=>imprimirEtiqueta(item)} style={{...btnPrimary,background:"#a855f7",marginTop:10,fontSize:11,padding:"7px 12px"}}>🏷️ Imprimir etiqueta</button>
              </div>
            </div>
            <div style={{display:"flex",gap:9,justifyContent:"flex-end",marginTop:8}}>
              <button onClick={()=>{setModalMovimiento(item.id);setCantMovimiento("");setFichaQR(null);}} style={{...btnPrimary,background:"#10b981"}}>+/− Ajustar stock</button>
              <button onClick={()=>{setForm({...item});setFichaQR(null);setModal(true);}} style={{...btnPrimary,background:"#3b82f6"}}>✏️ Editar</button>
              <button onClick={()=>setFichaQR(null)} style={btnOutline}>Cerrar</button>
            </div>
          </Modal>
        );
      })()}
    </div>
  );
};

// ── DOCUMENTACION ─────────────────────────────────────────
const Documentacion = ({ data, setData, filtroInicial, onFiltroConsumido }) => {
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({});
  const [archivos, setArchivos] = useState([]);
  const [vista, setVista] = useState(null);
  const [busqMarca, setBusqMarca] = useState("");
  const [busqModelo, setBusqModelo] = useState("");
  const [busqMatricula, setBusqMatricula] = useState("");
  const [busqAnyo, setBusqAnyo] = useState("");
  const [archivosAbiertos, setArchivosAbiertos] = useState({});
  // Archivos recien seleccionados a los que aun falta confirmar el tipo de documento
  // antes de quedar adjuntados de forma definitiva (ver modal de confirmacion mas abajo).
  const [archivosPendientes, setArchivosPendientes] = useState(null); // { destino:"modal"|docId, items:[...] }
  const f = k => e => setForm(p => ({...p, [k]: e.target.value}));

  // Llegada desde "Ver documentación" en la ficha de una máquina de un cliente:
  // si existe el documento de esa máquina concreta, abrirlo directamente;
  // si no (p.ej. máquina creada antes de existir este vínculo), al menos
  // dejamos los filtros de búsqueda rellenos con sus datos.
  useEffect(()=>{
    if(!filtroInicial) return;
    const {clienteId,maquinaId,marca,modelo,serie}=filtroInicial;
    const doc=(data.documentacion||[]).find(d=>d.clienteId===clienteId && d._maquinaClienteId===maquinaId);
    if(doc){
      setVista(doc.id);
    } else {
      setVista(null);
      setBusqMarca(marca||"");
      setBusqModelo(modelo||"");
      setBusqMatricula(serie||"");
      setBusqAnyo("");
    }
    if(onFiltroConsumido) onFiltroConsumido();
  },[filtroInicial]);

  const TIPOS_ARCHIVO = ["Manual de usuario","Manual de servicio","Despiece","Esquema electrico","Esquema hidraulico","Esquema neumatico","Lista de repuestos","Certificado","Otro"];

  const filtrados = (data.documentacion||[]).filter(d => {
    const q = (v, s) => !s || v?.toLowerCase().includes(s.toLowerCase());
    return q(d.marca, busqMarca) && q(d.modelo, busqModelo) && q(d.matricula, busqMatricula) && q(d.anyo, busqAnyo);
  });

  // Al seleccionar archivos no se adjuntan directamente: primero se piden los datos
  // (que tipo de documento es cada uno) en un modal de confirmacion; una vez confirmado
  // el tipo queda fijo y no se vuelve a poder cambiar con un desplegable suelto.
  const leerArchivosPendientes = (files, destino) => {
    const pendientes = [];
    let restantes = files.length;
    files.forEach(file => {
      const r = new FileReader();
      r.onload = ev => {
        pendientes.push({ nombre: file.name, tipo: detectarTipo(file.name), tamanyo: file.size, data: ev.target.result });
        restantes--;
        if (restantes === 0) setArchivosPendientes({ destino, items: pendientes });
      };
      r.readAsDataURL(file);
    });
  };

  const handleArchivos = e => {
    leerArchivosPendientes(Array.from(e.target.files), "modal");
    e.target.value = "";
  };

  // Subida rapida de documentos directamente desde la vista detalle (sin abrir el modal de edicion)
  const handleArchivosRapido = (e, docId) => {
    leerArchivosPendientes(Array.from(e.target.files), docId);
    e.target.value = "";
  };

  const confirmarArchivosPendientes = () => {
    if (!archivosPendientes) return;
    const finales = archivosPendientes.items.map(it => ({...it, id: Date.now()+Math.random()}));
    if (archivosPendientes.destino === "modal") {
      setArchivos(p => [...p, ...finales]);
    } else {
      const docId = archivosPendientes.destino;
      setData(d => ({...d, documentacion: (d.documentacion||[]).map(x => x.id===docId ? {...x, archivos:[...(x.archivos||[]), ...finales]} : x) }));
    }
    setArchivosPendientes(null);
  };

  const detectarTipo = nombre => {
    const n = nombre.toLowerCase();
    if (n.includes("manual")) return "Manual de usuario";
    if (n.includes("serv") || n.includes("taller")) return "Manual de servicio";
    if (n.includes("despiece") || n.includes("parts")) return "Despiece";
    if (n.includes("elec") || n.includes("wiring")) return "Esquema electrico";
    if (n.includes("hidra")) return "Esquema hidraulico";
    if (n.includes("neumat")) return "Esquema neumatico";
    return "Otro";
  };

  const iconoTipo = tipo => {
    if (tipo?.includes("Manual")) return "📖";
    if (tipo?.includes("Despiece")) return "🔩";
    if (tipo?.includes("electrico")) return "⚡";
    if (tipo?.includes("hidraulico")) return "💧";
    if (tipo?.includes("neumatico")) return "🌬️";
    if (tipo?.includes("repuestos")) return "🛒";
    if (tipo?.includes("Certificado")) return "📜";
    return "📄";
  };

  const colorTipo = tipo => {
    if (tipo?.includes("Manual")) return "#3b82f6";
    if (tipo?.includes("Despiece")) return "#f59e0b";
    if (tipo?.includes("electrico")) return "#faff00";
    if (tipo?.includes("hidraulico")) return "#06b6d4";
    if (tipo?.includes("neumatico")) return "#a855f7";
    if (tipo?.includes("repuestos")) return "#10b981";
    return "#6b7a99";
  };

  const formatBytes = b => b > 1048576 ? (b/1048576).toFixed(1)+" MB" : (b/1024).toFixed(0)+" KB";

  // Modal que pregunta el tipo de cada documento recien seleccionado, antes de adjuntarlo
  // de forma definitiva. Se muestra tanto desde el alta rapida (vista detalle) como desde
  // el formulario de Nueva/Editar maquina.
  const modalConfirmarTipos = archivosPendientes && (
    <Modal title={`¿Qué tipo de documento ${archivosPendientes.items.length>1?"son":"es"}?`} onClose={()=>setArchivosPendientes(null)}>
      <div style={{display:"grid",gap:8,marginBottom:12}}>
        {archivosPendientes.items.map((it,i)=>(
          <div key={i} style={{background:"#0d1117",borderRadius:8,padding:"10px 12px",border:"1px solid #2a3550"}}>
            <div style={{color:"#f1f3f9",fontSize:13,fontWeight:600,marginBottom:6,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.nombre}</div>
            <select value={it.tipo} onChange={e=>{
              const nuevoTipo = e.target.value;
              setArchivosPendientes(p=>({...p, items:p.items.map((x,j)=>j===i?{...x,tipo:nuevoTipo}:x)}));
            }} style={{...inputStyle,width:"100%"}}>
              {TIPOS_ARCHIVO.map(t=><option key={t} value={t}>{t}</option>)}
            </select>
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
        <button onClick={()=>setArchivosPendientes(null)} style={btnOutline}>Cancelar</button>
        <button onClick={confirmarArchivosPendientes} style={{...btnPrimary,background:"#e2b714",color:"#000",fontWeight:800}}>Confirmar y adjuntar</button>
      </div>
    </Modal>
  );

  const save = () => {
    if (!form.marca || !form.modelo) return alert("Marca y modelo son obligatorios");
    const item = {...form, archivos: archivos, fechaAlta: today()};
    if (!item.id) setData(d => ({...d, documentacion: [...(d.documentacion||[]), {...item, id: Date.now()}]}));
    else setData(d => ({...d, documentacion: (d.documentacion||[]).map(x => x.id===item.id ? item : x)}));
    setModal(false);
  };

  const openEdit = doc => {
    setForm({...doc});
    setArchivos([...(doc.archivos||[])]);
    setModal(true);
  };

  // Vista detalle
  const [modalPropietario, setModalPropietario] = useState(false);
  if (vista) {
    const doc = (data.documentacion||[]).find(d => d.id === vista);
    if (!doc) { setVista(null); return null; }
    const propietario = doc.clienteId ? data.clientes.find(c=>c.id===doc.clienteId) : null;
    // Partes vinculados a esta matricula
    const partesDoc = doc.matricula
      ? (data.partes||[]).filter(p=>p.matricula&&p.matricula.trim().toLowerCase()===doc.matricula.trim().toLowerCase())
      : [];
    return (
      <div>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:20}}>
          <button onClick={()=>setVista(null)} style={{background:"#2a3550",border:"none",borderRadius:8,padding:"7px 9px",cursor:"pointer",color:"#8892a4",display:"flex"}}><Icon name="back" size={15}/></button>
          <div style={{flex:1}}>
            <h2 style={{color:"#f1f3f9",fontWeight:800,fontSize:19,margin:0}}>{doc.marca} {doc.modelo}</h2>
            <div style={{display:"flex",gap:10,marginTop:2,flexWrap:"wrap"}}>
              {doc.matricula && <span style={{color:"#6b7a99",fontSize:12}}>Matr. {doc.matricula}</span>}
              {doc.anyo && <span style={{color:"#6b7a99",fontSize:12}}>Año {doc.anyo}</span>}
              {propietario && <span style={{background:"#faff00",color:"#1a1a00",borderRadius:5,padding:"2px 8px",fontSize:10,fontWeight:900}}>✓ PROPIETARIO: {propietario.nombreEmpresa}</span>}
              {!propietario && <span style={{background:"#6b7a9920",color:"#6b7a99",borderRadius:5,padding:"2px 8px",fontSize:10}}>Sin propietario asignado</span>}
              {doc.descripcion && <span style={{color:"#9aa3b8",fontSize:12}}>· {doc.descripcion}</span>}
            </div>
          </div>
          <button onClick={()=>setModalPropietario(true)} style={{background:"#faff0015",border:"1px solid #faff0044",borderRadius:8,padding:"7px 11px",color:"#faff00",fontSize:11,fontWeight:700,cursor:"pointer"}}>
            {propietario?"Cambiar propietario":"Asignar propietario"}
          </button>
          <button onClick={()=>openEdit(doc)} style={{...btnOutline,display:"flex",alignItems:"center",gap:5,padding:"7px 13px",fontSize:13}}><Icon name="edit" size={13}/>Editar</button>
          <button onClick={()=>{setData(d=>({...d,documentacion:(d.documentacion||[]).filter(x=>x.id!==doc.id)}));setVista(null);}} style={{...btnOutline,color:"#dc2626",borderColor:"#dc262644",padding:"7px 13px",fontSize:13}}>Eliminar</button>
        </div>

        {/* Modal cambiar propietario */}
        {modalPropietario && (
          <Modal title="Cambiar propietario de la maquina" onClose={()=>setModalPropietario(false)}>
            <div style={{background:"#0d1117",borderRadius:9,padding:"12px 14px",marginBottom:12}}>
              <div style={{fontSize:11,color:"#6b7a99",marginBottom:4}}>Propietario actual</div>
              <div style={{color:"#f1f3f9",fontWeight:700,fontSize:14}}>{propietario?.nombreEmpresa||"Sin propietario"}</div>
            </div>
            <Field label="Nuevo propietario">
              <ClientePicker clientes={data.clientes} value={doc.clienteId||""} onChange={id=>{
                setData(d=>({...d,documentacion:(d.documentacion||[]).map(x=>x.id===doc.id?{...x,clienteId:id}:x)}));
                setModalPropietario(false);
              }}/>
            </Field>
            <div style={{background:"#f59e0b12",border:"1px solid #f59e0b33",borderRadius:8,padding:"10px 12px",fontSize:12,color:"#f59e0b",marginTop:8}}>
              Al cambiar el propietario la maquina quedara vinculada al nuevo cliente. El historial de partes no cambia.
            </div>
            <div style={{display:"flex",gap:9,justifyContent:"flex-end",marginTop:12}}>
              <button onClick={()=>setModalPropietario(false)} style={btnOutline}>Cancelar</button>
            </div>
          </Modal>
        )}

        {/* Resumen */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(160px,100%),1fr))",gap:10,marginBottom:16}}>
          {[["Marca",doc.marca,"#e2b714"],["Modelo",doc.modelo,"#3b82f6"],["Matricula",doc.matricula||"—","#10b981"],["Año",doc.anyo||"—","#f59e0b"]].map(([l,v,c])=>(
            <div key={l} style={{background:"#151b2a",border:`1px solid ${c}33`,borderRadius:11,padding:"12px 14px"}}>
              <div style={{color:"#6b7a99",fontSize:10,textTransform:"uppercase",marginBottom:3}}>{l}</div>
              <div style={{color:c,fontWeight:800,fontSize:16}}>{v}</div>
            </div>
          ))}
        </div>

        {/* Partes de trabajo de esta maquina */}
        {partesDoc.length>0&&(
          <div style={{background:"#151b2a",border:"1px solid #0ea5e933",borderRadius:12,padding:"14px 16px",marginBottom:12}}>
            <div style={{fontSize:11,fontWeight:700,color:"#0ea5e9",textTransform:"uppercase",letterSpacing:".7px",marginBottom:10}}>Historial de partes — {partesDoc.length} parte{partesDoc.length!==1?"s":""}</div>
            <div style={{display:"grid",gap:6}}>
              {partesDoc.sort((a,b)=>b.fecha.localeCompare(a.fecha)).map(p=>{
                const cl=p.clienteDirectoId?data.clientes.find(c=>c.id===p.clienteDirectoId):null;
                return(
                  <div key={p.id} style={{background:"#0d1117",borderRadius:9,padding:"10px 13px",border:"1px solid #0ea5e922",display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
                    <div style={{flex:1}}>
                      <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap",marginBottom:2}}>
                        <span style={{color:"#0ea5e9",fontWeight:700,fontSize:12}}>{p.numeroParte||("PT-"+String(p.id).slice(-6))}</span>
                        <span style={{color:"#6b7a99",fontSize:11}}>· {fmtFecha(p.fecha)}</span>
                        <span style={{color:"#9aa3b8",fontSize:11}}>· {fmtNombres(p,"tecnicos","tecnico")}</span>
                        {cl&&<span style={{background:"#faff0015",color:"#faff00",borderRadius:4,padding:"0 5px",fontSize:10,fontWeight:700}}>{cl.nombreEmpresa}</span>}
                      </div>
                      <div style={{color:"#c4cad8",fontSize:12}}>{p.descripcion}</div>
                      {p.materialesList?.length>0&&<div style={{color:"#6b7a99",fontSize:11,marginTop:2}}>Materiales: {p.materialesList.map(m=>m.cantidad+"x "+m.material).join(", ")}</div>}
                    </div>
                    <div style={{textAlign:"right",flexShrink:0}}>
                      <div style={{color:"#f1f3f9",fontWeight:800,fontSize:15}}>{p.horasT}h</div>
                      <div style={{color:p.km>0||p.desplazamiento==="si"?"#10b981":"#6b7a99",fontSize:10}}>{p.km>0||p.desplazamiento==="si"?"Con desplaz.":"Sin desplaz."}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Archivos */}
        <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,overflow:"hidden"}}>
          <div style={{padding:"12px 16px",borderBottom:"1px solid #2a3550",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{color:"#f1f3f9",fontWeight:700,fontSize:14}}>{(doc.archivos||[]).length} documento{(doc.archivos||[]).length!==1?"s":""}</div>
            <label style={{display:"flex",alignItems:"center",gap:6,background:"#e2b71415",border:"1px solid #e2b71444",borderRadius:7,padding:"6px 12px",cursor:"pointer",color:"#e2b714",fontSize:12,fontWeight:700}}>
              📎 Añadir documento
              <input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.svg,.dwg" onChange={e=>handleArchivosRapido(e,doc.id)} style={{display:"none"}}/>
            </label>
          </div>
          {(doc.archivos||[]).length === 0 && <div style={{padding:"28px",textAlign:"center",color:"#6b7a99"}}>Sin archivos adjuntos</div>}
          {(doc.archivos||[]).map((a,i) => {
            const esPDF = a.data?.startsWith("data:application/pdf");
            const esImagen = a.data?.startsWith("data:image");
            const abierto = archivosAbiertos[doc.id+"-"+i];
            return (
              <div key={i} style={{borderBottom:"1px solid #1a2236"}}>
                <div style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px"}}>
                  <div style={{width:38,height:38,borderRadius:9,background:colorTipo(a.tipo)+"20",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0}}>{iconoTipo(a.tipo)}</div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{color:"#f1f3f9",fontWeight:600,fontSize:13,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{a.nombre}</div>
                    <div style={{display:"flex",gap:8,marginTop:2,alignItems:"center"}}>
                      <span style={{background:colorTipo(a.tipo)+"20",color:colorTipo(a.tipo),border:"1px solid "+colorTipo(a.tipo)+"44",borderRadius:4,padding:"1px 7px",fontSize:10,fontWeight:700}}>{a.tipo}</span>
                      <span style={{color:"#6b7a99",fontSize:11}}>{formatBytes(a.tamanyo||0)}</span>
                    </div>
                  </div>
                  <div style={{display:"flex",gap:6,flexShrink:0}}>
                    <a href={a.data} download={a.nombre} style={{background:"#2a3550",border:"1px solid #3a4560",borderRadius:7,padding:"6px 11px",color:"#8892a4",fontSize:12,fontWeight:700,textDecoration:"none"}}>↓</a>
                    {(esPDF||esImagen)&&(
                      <button onClick={()=>setArchivosAbiertos(p=>({...p,[doc.id+"-"+i]:!p[doc.id+"-"+i]}))}
                        style={{background:abierto?"#e2b714":"#e2b71420",border:"1px solid #e2b71444",borderRadius:7,padding:"6px 11px",color:abierto?"#000":"#e2b714",fontSize:12,fontWeight:700,cursor:"pointer"}}>
                        {abierto?"Cerrar":"👁 Ver"}
                      </button>
                    )}
                  </div>
                </div>
                {abierto && esPDF && (
                  <div style={{padding:"0 16px 14px"}}>
                    <iframe src={a.data} style={{width:"100%",height:520,border:"1px solid #2a3550",borderRadius:8,background:"#fff"}} title={a.nombre}/>
                  </div>
                )}
                {abierto && esImagen && (
                  <div style={{padding:"0 16px 14px",textAlign:"center",background:"#0d1117"}}>
                    <img src={a.data} alt={a.nombre} style={{maxWidth:"100%",maxHeight:480,borderRadius:8,border:"1px solid #2a3550"}}/>
                  </div>
                )}
              </div>
            );
          })}
        </div>
        {doc.notas && <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"14px 16px",marginTop:12}}><div style={{fontSize:11,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",marginBottom:6}}>Notas</div><div style={{color:"#9aa3b8",fontSize:13,lineHeight:1.6}}>{doc.notas}</div></div>}

        {modalConfirmarTipos}

        {/* Modal editar maquina (también accesible desde la vista detalle) */}
        {modal && (
          <Modal title={form.id?"Editar maquina":"Nueva maquina"} onClose={()=>setModal(false)} wide>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(170px,100%),1fr))",gap:11}}>
              <Field label="Marca *"><Input value={form.marca||""} onChange={f("marca")} placeholder="Casadei, Busellato..."/></Field>
              <Field label="Modelo *"><Input value={form.modelo||""} onChange={f("modelo")} placeholder="SC3, Jet Start..."/></Field>
              <Field label="Matricula / Nro serie"><Input value={form.matricula||""} onChange={f("matricula")}/></Field>
              <Field label="Año"><Input value={form.anyo||""} onChange={f("anyo")} placeholder="2022"/></Field>
            </div>
            <Field label="Cliente (propietario de la maquina)"><ClientePicker clientes={data.clientes} value={form.clienteId||""} onChange={id=>setForm(p=>({...p,clienteId:id}))}/></Field>
            <Field label="Descripcion breve"><Input value={form.descripcion||""} onChange={f("descripcion")} placeholder="Ej: Escuadradora de precision 3200mm"/></Field>

            {/* Subida de archivos */}
            <div style={{marginBottom:4}}>
              <div style={{fontSize:11,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>
                Documentos ({archivos.length})
              </div>
              <label style={{display:"flex",alignItems:"center",gap:8,background:"#0d1117",border:"1px dashed #e2b71444",borderRadius:8,padding:"12px 14px",cursor:"pointer",marginBottom:8}}>
                <span style={{fontSize:20}}>📎</span>
                <div>
                  <div style={{color:"#e2b714",fontWeight:700,fontSize:13}}>Añadir documentos</div>
                  <div style={{color:"#6b7a99",fontSize:11}}>PDF, imágenes, Word, Excel — sin limite</div>
                </div>
                <input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.svg,.dwg" onChange={handleArchivos} style={{display:"none"}}/>
              </label>

              {archivos.length > 0 && (
                <div style={{display:"grid",gap:5}}>
                  {archivos.map((a,i)=>(
                    <div key={i} style={{display:"flex",alignItems:"center",gap:10,background:"#0d1117",borderRadius:8,padding:"8px 12px",border:"1px solid #2a3550"}}>
                      <span style={{fontSize:16,flexShrink:0}}>{iconoTipo(a.tipo)}</span>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{a.nombre}</div>
                        <div style={{color:"#6b7a99",fontSize:10}}>{formatBytes(a.tamanyo||0)}</div>
                      </div>
                      <span style={{background:colorTipo(a.tipo)+"20",color:colorTipo(a.tipo),border:"1px solid "+colorTipo(a.tipo)+"44",borderRadius:4,padding:"2px 7px",fontSize:10,fontWeight:700,flexShrink:0}}>{a.tipo}</span>
                      <button onClick={()=>setArchivos(p=>p.filter((_,j)=>j!==i))} style={{background:"#3b1c1c",border:"none",borderRadius:5,padding:"4px 6px",color:"#dc2626",cursor:"pointer",flexShrink:0}}><Icon name="trash" size={11}/></button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <Field label="Notas"><Textarea value={form.notas||""} onChange={f("notas")} placeholder="Observaciones, notas de mantenimiento..."/></Field>
            <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
              <button onClick={()=>setModal(false)} style={btnOutline}>Cancelar</button>
              <button onClick={save} style={{...btnPrimary,background:"#e2b714",color:"#000",fontWeight:800}}>{form.id?"Guardar":"Crear ficha"}</button>
            </div>
          </Modal>
        )}
      </div>
    );
  }

  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
        <div>
          <h2 style={{color:"#f1f3f9",fontWeight:800,fontSize:22,margin:0}}>Documentacion</h2>
          <p style={{color:"#6b7a99",fontSize:13,margin:"3px 0 0"}}>Manuales · Despiece · Esquemas · Repuestos</p>
        </div>
        <button onClick={()=>{setForm({marca:"",modelo:"",matricula:"",anyo:"",descripcion:"",notas:""});setArchivos([]);setModal(true);}} style={{background:"linear-gradient(135deg,#e2b714,#f59e0b)",color:"#000",border:"none",borderRadius:9,padding:"9px 16px",fontWeight:800,cursor:"pointer",display:"flex",alignItems:"center",gap:6,fontSize:13}}>
          <Icon name="plus" size={14}/>Nueva maquina
        </button>
      </div>

      {/* Buscador por 4 parametros */}
      <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"16px",marginBottom:16}}>
        <div style={{fontSize:11,fontWeight:700,color:"#e2b714",textTransform:"uppercase",letterSpacing:".7px",marginBottom:10}}>Buscar documentacion</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(160px,100%),1fr))",gap:10}}>
          {[["Marca",busqMarca,setBusqMarca,"Ej: Casadei"],["Modelo",busqModelo,setBusqModelo,"Ej: SC3"],["Matricula",busqMatricula,setBusqMatricula,"Nro serie"],["Año",busqAnyo,setBusqAnyo,"Ej: 2022"]].map(([label,val,setVal,ph])=>(
            <div key={label}>
              <div style={{fontSize:10,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",marginBottom:4}}>{label}</div>
              <div style={{position:"relative"}}>
                <span style={{position:"absolute",left:8,top:"50%",transform:"translateY(-50%)",color:"#6b7a99"}}><Icon name="search" size={11}/></span>
                <input value={val} onChange={e=>setVal(e.target.value)} placeholder={ph} style={{...inputStyle,paddingLeft:26,width:"100%",boxSizing:"border-box"}}/>
              </div>
            </div>
          ))}
        </div>
        {(busqMarca||busqModelo||busqMatricula||busqAnyo) && (
          <button onClick={()=>{setBusqMarca("");setBusqModelo("");setBusqMatricula("");setBusqAnyo("");}} style={{marginTop:10,background:"none",border:"1px solid #2a3550",borderRadius:6,padding:"4px 12px",color:"#6b7a99",fontSize:12,cursor:"pointer"}}>Limpiar filtros ×</button>
        )}
      </div>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(140px,1fr))",gap:9,marginBottom:14}}>
        {[
          ["Maquinas",(data.documentacion||[]).length,"#e2b714"],
          ["Documentos",(data.documentacion||[]).reduce((s,d)=>s+(d.archivos||[]).length,0),"#3b82f6"],
          ["Resultados",filtrados.length,"#10b981"],
        ].map(([l,v,c])=>(
          <div key={l} style={{background:"#151b2a",border:`1px solid ${c}33`,borderRadius:11,padding:"11px 14px"}}>
            <div style={{color:c,fontWeight:800,fontSize:18,lineHeight:1}}>{v}</div>
            <div style={{color:"#6b7a99",fontSize:11,marginTop:3}}>{l}</div>
          </div>
        ))}
      </div>

      {/* Lista */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(300px,100%),1fr))",gap:10}}>
        {filtrados.length===0 && (
          <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"32px",textAlign:"center",color:"#6b7a99",gridColumn:"1/-1"}}>
            <div style={{fontSize:28,marginBottom:8}}>📂</div>
            <div style={{fontWeight:700,fontSize:14,color:"#f1f3f9",marginBottom:4}}>{(data.documentacion||[]).length===0?"Sin maquinas registradas":"Sin resultados para esta busqueda"}</div>
            <div style={{fontSize:12}}>Añade la primera maquina con sus documentos</div>
          </div>
        )}
        {filtrados.map(doc => {
          const nArchivos = (doc.archivos||[]).length;
          const tiposUnicos = [...new Set((doc.archivos||[]).map(a=>a.tipo))];
          return (
            <div key={doc.id} onClick={()=>setVista(doc.id)} style={{background:"#151b2a",border:"1px solid #e2b71433",borderRadius:12,padding:"15px 16px",cursor:"pointer",transition:"border-color .15s,transform .1s"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor="#e2b71488";e.currentTarget.style.transform="translateY(-1px)";}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor="#e2b71433";e.currentTarget.style.transform="none";}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8}}>
                <div>
                  <div style={{color:"#f1f3f9",fontWeight:800,fontSize:15}}>{doc.marca} <span style={{fontWeight:400}}>{doc.modelo}</span></div>
                  <div style={{display:"flex",gap:8,marginTop:3,flexWrap:"wrap"}}>
                    {doc.matricula && <span style={{color:"#6b7a99",fontSize:11}}>Matr. {doc.matricula}</span>}
                    {doc.anyo && <span style={{color:"#6b7a99",fontSize:11}}>Año {doc.anyo}</span>}
                  </div>
                </div>
                <div style={{background:"#e2b71420",color:"#e2b714",border:"1px solid #e2b71444",borderRadius:7,padding:"4px 10px",fontSize:12,fontWeight:800,flexShrink:0}}>{nArchivos} doc{nArchivos!==1?"s":""}</div>
              </div>
              {doc.descripcion && <div style={{color:"#9aa3b8",fontSize:12,marginBottom:8}}>{doc.descripcion}</div>}
              <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
                {tiposUnicos.slice(0,4).map(t=>(
                  <span key={t} style={{background:colorTipo(t)+"18",color:colorTipo(t),border:`1px solid ${colorTipo(t)}33`,borderRadius:4,padding:"2px 7px",fontSize:10,fontWeight:600}}>{iconoTipo(t)} {t}</span>
                ))}
                {tiposUnicos.length>4 && <span style={{color:"#6b7a99",fontSize:10}}>+{tiposUnicos.length-4} mas</span>}
              </div>
              {nArchivos===0 && <div style={{color:"#6b7a99",fontSize:11,fontStyle:"italic"}}>Sin documentos todavia</div>}
            </div>
          );
        })}
      </div>

      {/* Modal nueva/editar maquina */}
      {modal && (
        <Modal title={form.id?"Editar maquina":"Nueva maquina"} onClose={()=>setModal(false)} wide>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(170px,100%),1fr))",gap:11}}>
            <Field label="Marca *"><Input value={form.marca||""} onChange={f("marca")} placeholder="Casadei, Busellato..."/></Field>
            <Field label="Modelo *"><Input value={form.modelo||""} onChange={f("modelo")} placeholder="SC3, Jet Start..."/></Field>
            <Field label="Matricula / Nro serie"><Input value={form.matricula||""} onChange={f("matricula")}/></Field>
            <Field label="Año"><Input value={form.anyo||""} onChange={f("anyo")} placeholder="2022"/></Field>
          </div>
          <Field label="Cliente (propietario de la maquina)"><ClientePicker clientes={data.clientes} value={form.clienteId||""} onChange={id=>setForm(p=>({...p,clienteId:id}))}/></Field>
          <Field label="Descripcion breve"><Input value={form.descripcion||""} onChange={f("descripcion")} placeholder="Ej: Escuadradora de precision 3200mm"/></Field>

          {/* Subida de archivos */}
          <div style={{marginBottom:4}}>
            <div style={{fontSize:11,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>
              Documentos ({archivos.length})
            </div>
            <label style={{display:"flex",alignItems:"center",gap:8,background:"#0d1117",border:"1px dashed #e2b71444",borderRadius:8,padding:"12px 14px",cursor:"pointer",marginBottom:8}}>
              <span style={{fontSize:20}}>📎</span>
              <div>
                <div style={{color:"#e2b714",fontWeight:700,fontSize:13}}>Añadir documentos</div>
                <div style={{color:"#6b7a99",fontSize:11}}>PDF, imágenes, Word, Excel — sin limite</div>
              </div>
              <input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.svg,.dwg" onChange={handleArchivos} style={{display:"none"}}/>
            </label>

            {archivos.length > 0 && (
              <div style={{display:"grid",gap:5}}>
                {archivos.map((a,i)=>(
                  <div key={i} style={{display:"flex",alignItems:"center",gap:10,background:"#0d1117",borderRadius:8,padding:"8px 12px",border:"1px solid #2a3550"}}>
                    <span style={{fontSize:16,flexShrink:0}}>{iconoTipo(a.tipo)}</span>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{a.nombre}</div>
                      <div style={{color:"#6b7a99",fontSize:10}}>{formatBytes(a.tamanyo||0)}</div>
                    </div>
                    <span style={{background:colorTipo(a.tipo)+"20",color:colorTipo(a.tipo),border:"1px solid "+colorTipo(a.tipo)+"44",borderRadius:4,padding:"2px 7px",fontSize:10,fontWeight:700,flexShrink:0}}>{a.tipo}</span>
                    <button onClick={()=>setArchivos(p=>p.filter((_,j)=>j!==i))} style={{background:"#3b1c1c",border:"none",borderRadius:5,padding:"4px 6px",color:"#dc2626",cursor:"pointer",flexShrink:0}}><Icon name="trash" size={11}/></button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <Field label="Notas"><Textarea value={form.notas||""} onChange={f("notas")} placeholder="Observaciones, notas de mantenimiento..."/></Field>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={()=>setModal(false)} style={btnOutline}>Cancelar</button>
            <button onClick={save} style={{...btnPrimary,background:"#e2b714",color:"#000",fontWeight:800}}>{form.id?"Guardar":"Crear ficha"}</button>
          </div>
        </Modal>
      )}
      {modalConfirmarTipos}
    </div>
  );
};

// ── CALENDARIO ─────────────────────────────────────────────
const TIPOS_EVENTO = ["Aviso","Visita","Feria","Medico","Vacaciones","Formacion","Otro"];
const COLOR_EVENTO = {Aviso:"#ef4444",Visita:"#3b82f6",Feria:"#f59e0b",Medico:"#10b981",Vacaciones:"#a855f7",Formacion:"#06b6d4",Otro:"#6b7a99"};

const Calendario = ({ data, setData, userActual, irAAviso }) => {
  const esAdmin = userActual.rol==="manager"||userActual.rol==="admin";
  const [semanaOffset, setSemanaOffset] = useState(0);
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({});
  const [diaSeleccionado, setDiaSeleccionado] = useState(null);
  const [usuarioFiltro, setUsuarioFiltro] = useState(esAdmin?"todos":userActual.id);

  // Calcular dias de la semana actual + offset
  const getLunes = (offset) => {
    const hoy = new Date();
    const dia = hoy.getDay()||7;
    const lunes = new Date(hoy);
    lunes.setDate(hoy.getDate() - dia + 1 + offset*7);
    return lunes;
  };
  const lunes = getLunes(semanaOffset);
  const diasSemana = Array.from({length:7},(_,i)=>{
    const d = new Date(lunes);
    d.setDate(lunes.getDate()+i);
    return d;
  });
  const fmtDate = d => d.toISOString().split("T")[0];
  const fmtDia = d => d.toLocaleDateString("es-ES",{weekday:"short"}).replace(".","");
  const fmtNum = d => d.getDate();
  const fmtMes = d => d.toLocaleDateString("es-ES",{month:"long"});
  const esHoy = d => fmtDate(d)===today();

  // Eventos del calendario (guardados en data.calendario)
  const eventos = data.calendario||[];

  // Avisos como eventos — solo los que tienen fechaResolucion asignada
  const avisosEventos = data.avisos
    .filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado"&&a.fechaResolucion&&listaNombres(a,"asignados","asignado").length>0)
    .flatMap(a=>listaNombres(a,"asignados","asignado").map(nombre=>({
      id:"av-"+a.id+"-"+nombre, tipo:"Aviso", fecha:a.fechaResolucion,
      titulo:a.titulo,
      hora:a.horaResolucion||"",
      usuarioId: data.usuarios.find(u=>u.nombre===nombre)?.id||null,
      avisoId:a.id, color:"#ef4444", readOnly:true,
      clienteNombre:data.clientes.find(c=>c.id===a.clienteId)?.nombreEmpresa||"",
      prioridad:a.prioridad,
    })));

  const todosEventos = [...avisosEventos, ...eventos];

  const eventosDia = (fecha, uid) => todosEventos.filter(e=>{
    if(e.fecha!==fecha) return false;
    if(!esAdmin && uid==="todos") return e.usuarioId===userActual.id||!e.usuarioId;
    if(uid!=="todos") return e.usuarioId===parseInt(uid)||(!e.usuarioId&&esAdmin);
    return true;
  });

  const abrirNuevo = (fecha) => {
    setForm({fecha:fecha||today(),titulo:"",tipo:"Visita",usuarioId:userActual.id,notas:""});
    setModal(true);
  };

  const save = () => {
    if(!form.titulo?.trim()){alert("Escribe un titulo para el evento");return;}
    const item = {...form, usuarioId:parseInt(form.usuarioId)||userActual.id};
    if(!item.id) setData(d=>({...d,calendario:[...(d.calendario||[]),{...item,id:Date.now()}]}));
    else setData(d=>({...d,calendario:(d.calendario||[]).map(e=>e.id===item.id?item:e)}));
    setModal(false);
  };

  const delEvento = id => setData(d=>({...d,calendario:(d.calendario||[]).filter(e=>e.id!==id)}));

  const mesActual = fmtMes(lunes)+" "+lunes.getFullYear();

  return (
    <div>
      {/* Header */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <h2 style={{color:"#f1f3f9",fontWeight:800,fontSize:22,margin:0}}>Calendario</h2>
          <p style={{color:"#6b7a99",fontSize:13,margin:"3px 0 0",textTransform:"capitalize"}}>{mesActual}</p>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
          {esAdmin&&(
            <select value={usuarioFiltro} onChange={e=>setUsuarioFiltro(e.target.value)}
              style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:8,padding:"7px 11px",color:"#f1f3f9",fontSize:12,outline:"none"}}>
              <option value="todos">Todos los usuarios</option>
              {data.usuarios.filter(u=>u.activo).map(u=><option key={u.id} value={u.id}>{u.nombre}</option>)}
            </select>
          )}
          <div style={{display:"flex",gap:4}}>
            <button onClick={()=>setSemanaOffset(p=>p-1)} style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:7,padding:"7px 11px",color:"#f1f3f9",cursor:"pointer",fontSize:14}}>‹</button>
            <button onClick={()=>setSemanaOffset(0)} style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:7,padding:"7px 11px",color:"#f1f3f9",cursor:"pointer",fontSize:12}}>Hoy</button>
            <button onClick={()=>setSemanaOffset(p=>p+1)} style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:7,padding:"7px 11px",color:"#f1f3f9",cursor:"pointer",fontSize:14}}>›</button>
          </div>
          <button onClick={()=>abrirNuevo(today())} style={{background:"linear-gradient(135deg,#f97316,#ea580c)",color:"#fff",border:"none",borderRadius:9,padding:"9px 16px",fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:6,fontSize:13}}>
            <Icon name="plus" size={14}/>Nuevo evento
          </button>
        </div>
      </div>

      {/* Leyenda */}
      <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:12}}>
        {Object.entries(COLOR_EVENTO).map(([t,c])=>(
          <span key={t} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,color:"#9aa3b8"}}>
            <span style={{width:8,height:8,borderRadius:2,background:c,display:"inline-block"}}/>
            {t}
          </span>
        ))}
      </div>

      {/* Grid semana */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:6}}>
        {diasSemana.map(dia=>{
          const fecha = fmtDate(dia);
          const evsDia = eventosDia(fecha, usuarioFiltro);
          const hoy = esHoy(dia);
          const esFinSemana = dia.getDay()===0||dia.getDay()===6;
          return(
            <div key={fecha} style={{background:hoy?"#1e293b":"#151b2a",border:`1px solid ${hoy?"#f97316":"#2a3550"}`,borderRadius:10,padding:"8px 6px",minHeight:160,cursor:"pointer",transition:"border-color .15s"}}
              onClick={()=>abrirNuevo(fecha)}
              onMouseEnter={e=>e.currentTarget.style.borderColor=hoy?"#f97316":"#3b82f6"}
              onMouseLeave={e=>e.currentTarget.style.borderColor=hoy?"#f97316":"#2a3550"}>
              {/* Cabecera dia */}
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                <div style={{textAlign:"center",flex:1}}>
                  <div style={{color:esFinSemana?"#6b7a99":"#9aa3b8",fontSize:10,textTransform:"uppercase",letterSpacing:".5px"}}>{fmtDia(dia)}</div>
                  <div style={{width:26,height:26,borderRadius:13,background:hoy?"#f97316":"transparent",display:"flex",alignItems:"center",justifyContent:"center",margin:"2px auto 0",color:hoy?"#fff":"#f1f3f9",fontWeight:hoy?800:600,fontSize:14}}>
                    {fmtNum(dia)}
                  </div>
                </div>
                {evsDia.length>0&&<span style={{background:"#f97316",color:"#fff",borderRadius:10,padding:"0 5px",fontSize:10,fontWeight:800,minWidth:16,textAlign:"center"}}>{evsDia.length}</span>}
              </div>
              {/* Eventos del dia */}
              <div style={{display:"flex",flexDirection:"column",gap:3}}>
                {evsDia.slice(0,4).map(ev=>{
                  const uNombre = data.usuarios.find(u=>u.id===ev.usuarioId)?.nombre||"";
                  return(
                    <div key={ev.id} onClick={e=>{e.stopPropagation();if(!ev.readOnly){setForm({...ev});setModal(true);}}}
                      style={{background:COLOR_EVENTO[ev.tipo]+"22",border:"1px solid "+COLOR_EVENTO[ev.tipo]+"44",borderRadius:5,padding:"3px 5px",cursor:ev.readOnly?"default":"pointer"}}>
                      <div style={{color:COLOR_EVENTO[ev.tipo],fontSize:9,fontWeight:800,textTransform:"uppercase",letterSpacing:".3px"}}>{ev.hora?ev.hora+" — ":""}{ev.tipo}</div>
                      <div style={{color:"#e2e8f0",fontSize:10,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{ev.titulo}</div>
                      {ev.clienteNombre&&<div style={{color:"#94a3b8",fontSize:9,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{ev.clienteNombre}</div>}
                      {esAdmin&&(()=>{const uN=data.usuarios.find(u=>u.id===ev.usuarioId)?.nombre; return uN?<div style={{color:"#6b7a99",fontSize:9}}>{uN}</div>:null;})()}
                      {ev.prioridad&&<div style={{color:ev.prioridad==="Alta"?"#ef4444":ev.prioridad==="Media"?"#f59e0b":"#10b981",fontSize:9,fontWeight:700}}>{ev.prioridad}</div>}
                    </div>
                  );
                })}
                {evsDia.length>4&&<div style={{color:"#6b7a99",fontSize:10,textAlign:"center"}}>+{evsDia.length-4} mas</div>}
              </div>
            </div>
          );
        })}
      </div>

      {/* Proximos avisos pendientes del usuario */}
      {(()=>{
        const misAvisos = data.avisos.filter(a=>{
          if(a.estado==="Resuelto"||a.estado==="Cancelado") return false;
          if(!esAdmin) return listaNombres(a,"asignados","asignado").some(n=>data.usuarios.find(u=>u.nombre===n)?.id===userActual.id);
          return true;
        }).sort((a,b)=>(a.fechaResolucion||a.fechaAviso).localeCompare(b.fechaResolucion||b.fechaAviso)).slice(0,6);
        if(!misAvisos.length) return null;
        return(
          <div style={{marginTop:16,background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"14px 16px"}}>
            <div style={{fontSize:11,fontWeight:700,color:"#f97316",textTransform:"uppercase",letterSpacing:".7px",marginBottom:10}}>
              {esAdmin?"Proximos avisos pendientes":"Mis avisos pendientes"} ({misAvisos.length})
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(280px,100%),1fr))",gap:8}}>
              {misAvisos.map(av=>{
                const cl=data.clientes.find(c=>c.id===av.clienteId);
                const maq=av.maquinaId&&cl?cl.maquinas?.find(m=>m.id===parseInt(av.maquinaId)):null;
                const nombresAsig=listaNombres(av,"asignados","asignado").join(" y ");
                return(
                  <div key={av.id} onClick={()=>irAAviso&&irAAviso(av.id)}
                    style={{background:"#0d1117",borderRadius:8,padding:"9px 12px",cursor:irAAviso?"pointer":"default",border:"1px solid "+( av.prioridad==="Alta"?"#ef444433":av.prioridad==="Media"?"#f59e0b33":"#2a3550"),transition:"border-color .15s"}}
                    onMouseEnter={e=>irAAviso&&(e.currentTarget.style.borderColor="#3b82f6")}
                    onMouseLeave={e=>e.currentTarget.style.borderColor=av.prioridad==="Alta"?"#ef444433":av.prioridad==="Media"?"#f59e0b33":"#2a3550"}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:6,marginBottom:3}}>
                      <div style={{color:"#f1f3f9",fontWeight:700,fontSize:12,flex:1}}>{av.titulo}</div>
                      <span style={{background:av.prioridad==="Alta"?"#ef444420":av.prioridad==="Media"?"#f59e0b20":"#10b98120",color:av.prioridad==="Alta"?"#ef4444":av.prioridad==="Media"?"#f59e0b":"#10b981",borderRadius:4,padding:"1px 6px",fontSize:9,fontWeight:800,flexShrink:0}}>{av.prioridad}</span>
                    </div>
                    <div style={{color:"#6b7a99",fontSize:11}}>
                      📅 Aviso: {av.fechaAviso}
                      {av.fechaResolucion&&<span style={{color:"#3b82f6",fontWeight:700,marginLeft:8}}>🔧 Previsto: {av.fechaResolucion}{av.horaResolucion?" · "+av.horaResolucion:""}</span>}
                    </div>
                    {cl&&<div style={{color:"#6b7a99",fontSize:11}}>🏢 {cl.nombreEmpresa}</div>}
                    {maq&&<div style={{color:"#6b7a99",fontSize:11}}>🔧 {maq.nombre}</div>}
                    {esAdmin&&nombresAsig&&<div style={{color:"#3b82f6",fontSize:11}}>👤 {nombresAsig}</div>}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}

      {/* Modal nuevo/editar evento */}
      {modal&&(
        <Modal title={form.id?"Editar evento":"Nuevo evento"} onClose={()=>setModal(false)}>
          <Field label="Titulo del evento"><Input value={form.titulo||""} onChange={e=>setForm(p=>({...p,titulo:e.target.value}))} placeholder="Visita cliente, Feria Valencia..."/></Field>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(180px,100%),1fr))",gap:11}}>
            <Field label="Fecha"><Input type="date" value={form.fecha||today()} onChange={e=>setForm(p=>({...p,fecha:e.target.value}))}/></Field>
            <Field label="Tipo">
              <select value={form.tipo||"Visita"} onChange={e=>setForm(p=>({...p,tipo:e.target.value}))} style={{...inputStyle}}>
                {TIPOS_EVENTO.filter(t=>t!=="Aviso").map(t=><option key={t} value={t}>{t}</option>)}
              </select>
            </Field>
          </div>
          {esAdmin&&(
            <Field label="Asignar a">
              <select value={form.usuarioId||userActual.id} onChange={e=>setForm(p=>({...p,usuarioId:parseInt(e.target.value)}))} style={{...inputStyle}}>
                {data.usuarios.filter(u=>u.activo).map(u=><option key={u.id} value={u.id}>{u.nombre} — {u.rol}</option>)}
              </select>
            </Field>
          )}
          <Field label="Notas"><Textarea value={form.notas||""} onChange={e=>setForm(p=>({...p,notas:e.target.value}))} placeholder="Detalles del evento..."/></Field>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            {form.id&&<button onClick={()=>{delEvento(form.id);setModal(false);}} style={{...btnOutline,color:"#dc2626",borderColor:"#dc262644"}}>Eliminar</button>}
            <button onClick={()=>setModal(false)} style={btnOutline}>Cancelar</button>
            <button onClick={save} style={{...btnPrimary,background:"#f97316"}}>Guardar</button>
          </div>
        </Modal>
      )}
    </div>
  );
};



// ─── FICHAJE ────────────────────────────────────────────────────────────────
const Fichaje = ({ data, setData, userActual }) => {
  const hoy = today();
  const [mesVer, setMesVer] = useState(hoy.slice(0,7));
  const [modal, setModal] = useState(null);
  const [form, setForm] = useState({fecha:hoy,entrada:"",salida:"",pausaIni:"",pausaFin:"",notas:""});
  const f = k => e => setForm(p=>({...p,[k]:e.target.value}));
  // Modal exportar PDF
  const [modalExport, setModalExport] = useState(false);
  const [expForm, setExpForm] = useState({
    userId: userActual.id,
    fechaIni: hoy.slice(0,7)+"-01",
    fechaFin: hoy,
    nombreCompleto: "",
    dni: ""
  });
  const ef = k => e => setExpForm(p=>({...p,[k]:e.target.value}));

  const misRegistros = (data.fichajes||[]).filter(r=>r.userId===userActual.id);
  const fichajeHoy = misRegistros.find(r=>r.fecha===hoy);

  // Minutos de pausa calculados desde hora inicio y fin de pausa
  const calcPausaMins = (pausaIni, pausaFin) => {
    if(!pausaIni||!pausaFin) return 0;
    const [ph,pm]=pausaIni.split(":").map(Number);
    const [fh,fm]=pausaFin.split(":").map(Number);
    const mins=(fh*60+fm)-(ph*60+pm);
    return mins>0?mins:0;
  };

  // Minutos netos (descontando pausa)
  const calcMinutosNetos = (entrada, salida, pausaIni, pausaFin) => {
    if(!entrada||!salida) return 0;
    const [eh,em]=entrada.split(":").map(Number);
    const [sh,sm]=salida.split(":").map(Number);
    const bruto=(sh*60+sm)-(eh*60+em);
    const pausaMins=calcPausaMins(pausaIni,pausaFin);
    const neto=bruto-pausaMins;
    return neto>0?neto:0;
  };

  const calcHorasNetas = (entrada, salida, pausaIni, pausaFin) => {
    const mins=calcMinutosNetos(entrada,salida,pausaIni,pausaFin);
    if(!mins) return null;
    const h=Math.floor(mins/60),m=mins%60;
    return `${h}h ${m.toString().padStart(2,"0")}m`;
  };

  const ficharEntrada = () => {
    const ahora=new Date().toTimeString().slice(0,5);
    const nuevo={id:uid(),userId:userActual.id,fecha:hoy,entrada:ahora,salida:"",pausaIni:"",pausaFin:"",notas:""};
    setData(d=>({...d,fichajes:[...(d.fichajes||[]),nuevo]}));
  };

  const ficharSalida = () => {
    const ahora=new Date().toTimeString().slice(0,5);
    setData(d=>({...d,fichajes:(d.fichajes||[]).map(r=>r.id===fichajeHoy.id?{...r,salida:ahora}:r)}));
  };

  const guardar = () => {
    if(!form.fecha||!form.entrada){alert("Fecha y hora de entrada son obligatorias.");return;}
    if(modal.modo==="nuevo"){
      const existe=misRegistros.find(r=>r.fecha===form.fecha);
      if(existe){alert("Ya existe un registro para ese día. Edítalo desde el historial.");return;}
      setData(d=>({...d,fichajes:[...(d.fichajes||[]),{id:uid(),userId:userActual.id,...form}]}));
    } else {
      setData(d=>({...d,fichajes:(d.fichajes||[]).map(r=>r.id===modal.registro.id?{...r,...form}:r)}));
    }
    setModal(null);
  };

  const abrirNuevo = () => {setForm({fecha:hoy,entrada:"",salida:"",pausaIni:"",pausaFin:"",notas:""});setModal({modo:"nuevo"});};
  const abrirEditar = r => {setForm({fecha:r.fecha,entrada:r.entrada,salida:r.salida||"",pausaIni:r.pausaIni||"",pausaFin:r.pausaFin||"",notas:r.notas||""});setModal({modo:"editar",registro:r});};
  const borrar = id => {if(window.confirm("¿Eliminar este registro?"))setData(d=>({...d,fichajes:(d.fichajes||[]).filter(r=>r.id!==id)}));};

  // Filtrar por mes
  const registrosMes = misRegistros.filter(r=>r.fecha.startsWith(mesVer)).sort((a,b)=>b.fecha.localeCompare(a.fecha));
  const totalMinMes = registrosMes.reduce((acc,r)=>acc+calcMinutosNetos(r.entrada,r.salida,r.pausaIni,r.pausaFin),0);
  const totalHMes=Math.floor(totalMinMes/60), totalMMes=totalMinMes%60;

  // Semana actual
  const hoyDate=new Date(hoy);
  const diaSemana=hoyDate.getDay()===0?6:hoyDate.getDay()-1;
  const lunesSemana=new Date(hoyDate); lunesSemana.setDate(hoyDate.getDate()-diaSemana);
  const registrosSemana=misRegistros.filter(r=>{const rd=new Date(r.fecha);return rd>=lunesSemana&&rd<=hoyDate;});
  const totalMinSemana=registrosSemana.reduce((acc,r)=>acc+calcMinutosNetos(r.entrada,r.salida,r.pausaIni,r.pausaFin),0);
  const totalHSem=Math.floor(totalMinSemana/60), totalMSem=totalMinSemana%60;

  const estadoHoy=!fichajeHoy?"sin_fichar":fichajeHoy.salida?"completo":"fichado_entrada";

  const meses=[];
  for(let i=0;i<6;i++){const d=new Date();d.setMonth(d.getMonth()-i);meses.push(d.toISOString().slice(0,7));}

  // ── EXPORTAR PDF ────────────────────────────────────────────────────────────
  const exportarPDF = async () => {
    if(!expForm.nombreCompleto.trim()){alert("Introduce el nombre completo del trabajador.");return;}
    if(!expForm.dni.trim()){alert("Introduce el DNI/NIE del trabajador.");return;}
    const registrosExp = (data.fichajes||[])
      .filter(r=>r.userId===parseInt(expForm.userId)&&r.fecha>=expForm.fechaIni&&r.fecha<=expForm.fechaFin)
      .sort((a,b)=>a.fecha.localeCompare(b.fecha));

    const { default: jsPDF } = await import(/* @vite-ignore */ "https://cdn.skypack.dev/jspdf@2.5.1");
    const doc = new jsPDF({orientation:"portrait",unit:"mm",format:"a4"});
    const W=210, mg=14;

    // ── Cabecera empresa ──
    doc.setFillColor(15,23,42); doc.rect(0,0,W,34,"F");
    doc.setFillColor(245,158,11); doc.rect(0,32,W,2.5,"F");
    doc.setDrawColor(255,255,255);
    try { doc.addImage(LOGO_CIRCULO,"JPEG",mg,3,26,26); } catch(e){}
    doc.setTextColor(255,255,255); doc.setFontSize(13); doc.setFont("helvetica","bold");
    doc.text("EUROPEA DE MAQUINARIA PMM SL",mg+30,12);
    doc.setFontSize(7); doc.setFont("helvetica","normal"); doc.setTextColor(190,200,220);
    doc.text("Carrer Mas del Jutge 33  ·  46900 Torrent (Valencia)  ·  CIF: B98527583",mg+30,18);
    doc.text("europeademaquinaria.com  ·  info@europeademaquinaria.com",mg+30,24);
    doc.setFillColor(255,255,255); doc.rect(0,34.5,W,262,"F");

    // ── Título ──
    doc.setTextColor(15,23,42); doc.setFontSize(16); doc.setFont("helvetica","bold");
    doc.text("REGISTRO DE JORNADA LABORAL",W/2,46,{align:"center"});
    doc.setFontSize(10); doc.setFont("helvetica","normal"); doc.setTextColor(80,90,110);
    doc.text(`Período: ${fmtFecha(expForm.fechaIni)} — ${fmtFecha(expForm.fechaFin)}`,W/2,53,{align:"center"});

    // ── Datos trabajador ──
    let y=62;
    doc.setFillColor(230,235,245); doc.roundedRect(mg,y,W-mg*2,7,1,1,"F");
    doc.setTextColor(40,60,110); doc.setFontSize(8); doc.setFont("helvetica","bold");
    doc.text("DATOS DEL TRABAJADOR",mg+4,y+5); y+=11;
    doc.setDrawColor(255,255,255);
    // Fila datos
    doc.setFillColor(248,250,255); doc.rect(mg,y,W-mg*2,20,"F");
    doc.setDrawColor(220,225,240); doc.rect(mg,y,W-mg*2,20,"S");
    doc.setDrawColor(255,255,255);
    doc.setTextColor(100,115,145); doc.setFontSize(7.5); doc.setFont("helvetica","normal");
    doc.text("Nombre completo:",mg+4,y+7);
    doc.text("DNI / NIE:",mg+4,y+15);
    doc.setTextColor(25,35,60); doc.setFontSize(10); doc.setFont("helvetica","bold");
    doc.text(expForm.nombreCompleto,mg+45,y+7);
    doc.text(expForm.dni,mg+45,y+15);
    y+=26;

    // ── Tabla registros ──
    doc.setFillColor(40,60,110); doc.rect(mg,y,W-mg*2,7,"F");
    doc.setTextColor(255,255,255); doc.setFontSize(8); doc.setFont("helvetica","bold");
    const cols=[mg+3,mg+32,mg+58,mg+83,mg+108,mg+133];
    ["Fecha","Entrada","Salida","Pausa","H. Brutas","H. Netas"].forEach((h,i)=>doc.text(h,cols[i],y+5));
    y+=8;

    let totalBruto=0, totalNeto=0;
    registrosExp.forEach((r,i)=>{
      const rowH = r.notas ? 14 : 8;
      if(y+rowH>270){doc.addPage();doc.setFillColor(255,255,255);doc.rect(0,0,W,297,"F");y=15;}
      const bgClr=i%2===0?[248,250,255]:[255,255,255];
      doc.setFillColor(...bgClr); doc.rect(mg,y-1,W-mg*2,rowH,"F");
      doc.setDrawColor(255,255,255);

      // Calcular pausa
      let pausaMins=0, pausaStr="—";
      if(r.pausaIni&&r.pausaFin){
        const [ph,pm]=r.pausaIni.split(":").map(Number);
        const [fh,fm]=r.pausaFin.split(":").map(Number);
        pausaMins=(fh*60+fm)-(ph*60+pm);
        if(pausaMins>0) pausaStr=`${r.pausaIni}-${r.pausaFin}`;
        else pausaMins=0;
      }

      let hBruto="—", hNeto="—";
      if(r.entrada&&r.salida){
        const [eh,em]=r.entrada.split(":").map(Number);
        const [sh,sm]=r.salida.split(":").map(Number);
        const bruto=(sh*60+sm)-(eh*60+em);
        if(bruto>0){
          totalBruto+=bruto;
          const hb=Math.floor(bruto/60),mb=bruto%60;
          hBruto=`${hb}h${mb.toString().padStart(2,"0")}m`;
          const neto=bruto-pausaMins;
          if(neto>0){
            totalNeto+=neto;
            const hn=Math.floor(neto/60),mn=neto%60;
            hNeto=`${hn}h${mn.toString().padStart(2,"0")}m`;
          }
        }
      }
      doc.setTextColor(30,40,70); doc.setFontSize(8.5); doc.setFont("helvetica","normal");
      doc.text(fmtFecha(r.fecha),cols[0],y+5);
      doc.setFont("helvetica","bold"); doc.setTextColor(16,120,80);
      doc.text(r.entrada||"—",cols[1],y+5);
      doc.setTextColor(180,30,30);
      doc.text(r.salida||"—",cols[2],y+5);
      doc.setTextColor(100,115,145); doc.setFont("helvetica","normal"); doc.setFontSize(7.5);
      doc.text(pausaStr,cols[3],y+5);
      doc.setFontSize(8.5); doc.setTextColor(60,80,140); doc.setFont("helvetica","bold");
      doc.text(hBruto,cols[4],y+5);
      doc.setTextColor(15,100,55);
      doc.text(hNeto,cols[5],y+5);
      if(r.notas){
        doc.setTextColor(130,140,160); doc.setFontSize(7); doc.setFont("helvetica","italic");
        doc.text("  Nota: "+r.notas,cols[0],y+10);
      }
      y+=rowH;
    });

    // ── Totales ──
    y+=4;
    doc.setFillColor(40,60,110); doc.rect(mg,y,W-mg*2,9,"F");
    doc.setDrawColor(255,255,255);
    doc.setTextColor(255,255,255); doc.setFontSize(9); doc.setFont("helvetica","bold");
    doc.text("TOTAL",cols[0],y+6);
    const tbH=Math.floor(totalBruto/60),tbM=totalBruto%60;
    const tnH=Math.floor(totalNeto/60),tnM=totalNeto%60;
    doc.text(`${tbH}h${tbM.toString().padStart(2,"0")}m`,cols[4],y+6);
    doc.setTextColor(100,255,180);
    doc.text(`${tnH}h${tnM.toString().padStart(2,"0")}m`,cols[5],y+6);
    y+=16;

    // ── Firma ──
    doc.setDrawColor(180,190,210);
    doc.line(mg,y+15,mg+70,y+15);
    doc.line(W-mg-70,y+15,W-mg,y+15);
    doc.setDrawColor(255,255,255);
    doc.setTextColor(100,115,145); doc.setFontSize(8); doc.setFont("helvetica","normal");
    doc.text("Firma del trabajador",mg+35,y+20,{align:"center"});
    doc.text("Firma y sello empresa",W-mg-35,y+20,{align:"center"});

    // ── Pie ──
    doc.setFillColor(245,158,11); doc.rect(0,281,W,1.5,"F");
    doc.setFillColor(15,23,42); doc.rect(0,282.5,W,14.5,"F");
    doc.setTextColor(190,200,220); doc.setFontSize(7); doc.setFont("helvetica","normal");
    doc.text(`Documento generado el ${fmtFecha(hoy)}  ·  Europea de Maquinaria PMM SL  ·  CIF: B98527583`,W/2,291,{align:"center"});

    doc.save(`fichaje_${expForm.nombreCompleto.replace(/ /g,"_")}_${expForm.fechaIni}_${expForm.fechaFin}.pdf`);
    setModalExport(false);
  };

  // Usuarios disponibles para exportar (manager/admin ven todos)
  const usuariosExport = (userActual.rol==="manager"||userActual.rol==="admin")
    ? data.usuarios.filter(u=>u.activo)
    : [data.usuarios.find(u=>u.id===userActual.id)].filter(Boolean);

  return (
    <div style={{maxWidth:700,margin:"0 auto"}}>
      {/* Header */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20,flexWrap:"wrap",gap:10}}>
        <div>
          <h2 style={{color:"#f1f3f9",fontWeight:800,fontSize:22,margin:0}}>Control de Fichaje</h2>
          <p style={{color:"#6b7a99",fontSize:12,margin:"2px 0 0"}}>{userActual.nombre} · {fmtFecha(hoy)}</p>
        </div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>{
            setExpForm({userId:userActual.id,fechaIni:hoy.slice(0,7)+"-01",fechaFin:hoy,nombreCompleto:"",dni:""});
            setModalExport(true);
          }} style={{background:"#f59e0b20",border:"1px solid #f59e0b44",borderRadius:9,padding:"8px 14px",color:"#f59e0b",fontWeight:700,cursor:"pointer",fontSize:13,display:"flex",alignItems:"center",gap:6}}>
            <Icon name="parts" size={14}/>Exportar PDF
          </button>
          <button onClick={abrirNuevo} style={{background:"#14b8a620",border:"1px solid #14b8a644",borderRadius:9,padding:"8px 14px",color:"#14b8a6",fontWeight:700,cursor:"pointer",fontSize:13,display:"flex",alignItems:"center",gap:6}}>
            <Icon name="plus" size={14}/>Añadir registro
          </button>
        </div>
      </div>

      {/* Tarjeta HOY */}
      <div style={{background:"#151b2a",border:`2px solid ${estadoHoy==="completo"?"#14b8a6":estadoHoy==="fichado_entrada"?"#f59e0b":"#2a3550"}`,borderRadius:16,padding:"20px 22px",marginBottom:20}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
          <div style={{fontWeight:800,fontSize:16,color:"#f1f3f9"}}>Hoy — {fmtFecha(hoy)}</div>
          {estadoHoy==="completo"&&<span style={{background:"#14b8a620",color:"#14b8a6",borderRadius:7,padding:"3px 10px",fontSize:12,fontWeight:700}}>✓ Completado</span>}
          {estadoHoy==="fichado_entrada"&&<span style={{background:"#f59e0b20",color:"#f59e0b",borderRadius:7,padding:"3px 10px",fontSize:12,fontWeight:700}}>⏱ En curso</span>}
          {estadoHoy==="sin_fichar"&&<span style={{background:"#6b7a9920",color:"#6b7a99",borderRadius:7,padding:"3px 10px",fontSize:12,fontWeight:700}}>Sin fichar</span>}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr",gap:10,marginBottom:16}}>
          <div style={{background:"#0d1117",borderRadius:10,padding:"11px 12px",textAlign:"center"}}>
            <div style={{color:"#6b7a99",fontSize:9,fontWeight:700,textTransform:"uppercase",marginBottom:3}}>Entrada</div>
            <div style={{color:fichajeHoy?.entrada?"#10b981":"#2a3550",fontSize:20,fontWeight:900}}>{fichajeHoy?.entrada||"--:--"}</div>
          </div>
          <div style={{background:"#0d1117",borderRadius:10,padding:"11px 12px",textAlign:"center"}}>
            <div style={{color:"#6b7a99",fontSize:9,fontWeight:700,textTransform:"uppercase",marginBottom:3}}>Salida</div>
            <div style={{color:fichajeHoy?.salida?"#ef4444":"#2a3550",fontSize:20,fontWeight:900}}>{fichajeHoy?.salida||"--:--"}</div>
          </div>
          <div style={{background:"#0d1117",borderRadius:10,padding:"11px 12px",textAlign:"center"}}>
            <div style={{color:"#6b7a99",fontSize:9,fontWeight:700,textTransform:"uppercase",marginBottom:3}}>Pausa</div>
            <div style={{color:fichajeHoy?.pausaIni&&fichajeHoy?.pausaFin?"#f59e0b":"#2a3550",fontSize:13,fontWeight:900,lineHeight:1.3}}>
              {fichajeHoy?.pausaIni&&fichajeHoy?.pausaFin?<>{fichajeHoy.pausaIni}<br/>{fichajeHoy.pausaFin}</>:"—"}
            </div>
          </div>
          <div style={{background:"#0d1117",borderRadius:10,padding:"11px 12px",textAlign:"center"}}>
            <div style={{color:"#6b7a99",fontSize:9,fontWeight:700,textTransform:"uppercase",marginBottom:3}}>H. Netas</div>
            <div style={{color:fichajeHoy?.salida?"#14b8a6":"#2a3550",fontSize:20,fontWeight:900}}>
              {fichajeHoy?.entrada&&fichajeHoy?.salida?calcHorasNetas(fichajeHoy.entrada,fichajeHoy.salida,fichajeHoy.pausaIni,fichajeHoy.pausaFin):"--"}
            </div>
          </div>
        </div>
        <div style={{display:"flex",gap:10}}>
          {estadoHoy==="sin_fichar"&&<button onClick={ficharEntrada} style={{flex:1,background:"#10b981",border:"none",borderRadius:10,padding:"12px",color:"#fff",fontWeight:800,cursor:"pointer",fontSize:15,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}><Icon name="clock" size={18}/>Fichar Entrada</button>}
          {estadoHoy==="fichado_entrada"&&<button onClick={ficharSalida} style={{flex:1,background:"#ef4444",border:"none",borderRadius:10,padding:"12px",color:"#fff",fontWeight:800,cursor:"pointer",fontSize:15,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}><Icon name="clock" size={18}/>Fichar Salida</button>}
          {estadoHoy!=="sin_fichar"&&<button onClick={()=>abrirEditar(fichajeHoy)} style={{background:"#2a3550",border:"1px solid #3a4560",borderRadius:10,padding:"12px 16px",color:"#94a3b8",fontWeight:700,cursor:"pointer",fontSize:13}}>✏️ Editar</button>}
        </div>
      </div>

      {/* Resumen semana y mes */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:20}}>
        <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#6b7a99",fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Esta semana</div>
          <div style={{color:"#14b8a6",fontSize:26,fontWeight:900}}>{totalHSem}h {totalMSem.toString().padStart(2,"0")}m</div>
          <div style={{color:"#6b7a99",fontSize:11,marginTop:2}}>{registrosSemana.length} día{registrosSemana.length!==1?"s":""} fichado{registrosSemana.length!==1?"s":""}</div>
        </div>
        <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#6b7a99",fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Este mes</div>
          <div style={{color:"#f59e0b",fontSize:26,fontWeight:900}}>{totalHMes}h {totalMMes.toString().padStart(2,"0")}m</div>
          <div style={{color:"#6b7a99",fontSize:11,marginTop:2}}>{registrosMes.length} día{registrosMes.length!==1?"s":""} fichado{registrosMes.length!==1?"s":""}</div>
        </div>
      </div>

      {/* Historial */}
      <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"16px 18px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
          <div style={{fontWeight:700,fontSize:14,color:"#f1f3f9"}}>Historial</div>
          <select value={mesVer} onChange={e=>setMesVer(e.target.value)} style={{...inputStyle,width:"auto",fontSize:12,padding:"5px 10px"}}>
            {meses.map(m=>{const [y,mo]=m.split("-");const nom=new Date(parseInt(y),parseInt(mo)-1,1).toLocaleDateString("es-ES",{month:"long",year:"numeric"});return <option key={m} value={m}>{nom.charAt(0).toUpperCase()+nom.slice(1)}</option>;})}
          </select>
        </div>
        {registrosMes.length===0&&<div style={{color:"#6b7a99",fontSize:13,textAlign:"center",padding:"20px 0"}}>No hay registros este mes</div>}
        {registrosMes.map(r=>(
          <div key={r.id} style={{display:"grid",gridTemplateColumns:"100px 60px 60px 55px 70px 1fr auto",gap:6,alignItems:"center",padding:"9px 10px",borderRadius:8,marginBottom:4,background:r.fecha===hoy?"#14b8a610":"#0d1117",border:`1px solid ${r.fecha===hoy?"#14b8a630":"#1a2236"}`}}>
            <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600}}>{fmtFecha(r.fecha)}</div>
            <div style={{textAlign:"center"}}><div style={{color:"#6b7a99",fontSize:9,textTransform:"uppercase"}}>Entrada</div><div style={{color:"#10b981",fontWeight:700,fontSize:13}}>{r.entrada||"--:--"}</div></div>
            <div style={{textAlign:"center"}}><div style={{color:"#6b7a99",fontSize:9,textTransform:"uppercase"}}>Salida</div><div style={{color:r.salida?"#ef4444":"#6b7a99",fontWeight:700,fontSize:13}}>{r.salida||"--:--"}</div></div>
            <div style={{textAlign:"center"}}><div style={{color:"#6b7a99",fontSize:9,textTransform:"uppercase"}}>Pausa</div><div style={{color:r.pausaIni&&r.pausaFin?"#f59e0b":"#6b7a99",fontWeight:700,fontSize:11}}>{r.pausaIni&&r.pausaFin?`${r.pausaIni}-${r.pausaFin}`:"—"}</div></div>
            <div style={{textAlign:"center"}}><div style={{color:"#6b7a99",fontSize:9,textTransform:"uppercase"}}>Netas</div><div style={{color:r.salida?"#14b8a6":"#6b7a99",fontWeight:700,fontSize:13}}>{r.salida?calcHorasNetas(r.entrada,r.salida,r.pausaIni,r.pausaFin):"—"}</div></div>
            <div style={{color:"#6b7a99",fontSize:11,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.notas||""}</div>
            <div style={{display:"flex",gap:5}}>
              <button onClick={()=>abrirEditar(r)} style={{background:"#2a3550",border:"none",borderRadius:6,padding:"4px 8px",color:"#94a3b8",cursor:"pointer",fontSize:11}}>✏️</button>
              <button onClick={()=>borrar(r.id)} style={{background:"#dc262615",border:"none",borderRadius:6,padding:"4px 8px",color:"#dc2626",cursor:"pointer",fontSize:11}}>✕</button>
            </div>
          </div>
        ))}
      </div>

      {/* Resumen equipo - solo manager/admin */}
      {(userActual.rol==="manager"||userActual.rol==="admin")&&(
        <div style={{marginTop:20,background:"#151b2a",border:"1px solid #2a3550",borderRadius:12,padding:"16px 18px"}}>
          <div style={{fontWeight:700,fontSize:14,color:"#f1f3f9",marginBottom:14}}>Resumen equipo — {new Date(mesVer+"-01").toLocaleDateString("es-ES",{month:"long",year:"numeric"})}</div>
          {data.usuarios.filter(u=>u.activo&&u.id!==userActual.id).map(u=>{
            const regs=(data.fichajes||[]).filter(r=>r.userId===u.id&&r.fecha.startsWith(mesVer));
            const mins=regs.reduce((acc,r)=>acc+calcMinutosNetos(r.entrada,r.salida,r.pausaIni,r.pausaFin),0);
            const h=Math.floor(mins/60),m=mins%60;
            return(
              <div key={u.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 10px",borderRadius:8,background:"#0d1117",marginBottom:5}}>
                <div style={{display:"flex",alignItems:"center",gap:9}}>
                  <div style={{width:30,height:30,borderRadius:7,background:ROLES_COLOR[u.rol]+"30",display:"flex",alignItems:"center",justifyContent:"center",color:ROLES_COLOR[u.rol],fontWeight:800,fontSize:11}}>{inic(u.nombre)}</div>
                  <div><div style={{color:"#f1f3f9",fontSize:13,fontWeight:600}}>{u.nombre}</div><RolBadge rol={u.rol}/></div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{color:"#14b8a6",fontWeight:800,fontSize:15}}>{h}h {m.toString().padStart(2,"0")}m</div>
                  <div style={{color:"#6b7a99",fontSize:11}}>{regs.length} días</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal nuevo/editar registro */}
      {modal&&(
        <Modal title={modal.modo==="nuevo"?"Añadir registro":"Editar registro"} onClose={()=>setModal(null)}>
          <Field label="Fecha"><Input type="date" value={form.fecha} onChange={f("fecha")}/></Field>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:11}}>
            <Field label="Hora de entrada *"><Input type="time" value={form.entrada} onChange={f("entrada")}/></Field>
            <Field label="Hora de salida"><Input type="time" value={form.salida} onChange={f("salida")}/></Field>
          </div>
          <div style={{background:"#0d1117",borderRadius:9,padding:"12px 14px",border:"1px solid #2a3550"}}>
            <div style={{color:"#f59e0b",fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:8}}>Pausa / Descanso (opcional)</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:11}}>
              <Field label="Inicio pausa"><Input type="time" value={form.pausaIni} onChange={f("pausaIni")}/></Field>
              <Field label="Fin pausa"><Input type="time" value={form.pausaFin} onChange={f("pausaFin")}/></Field>
            </div>
            {form.pausaIni&&form.pausaFin&&(()=>{
              const [ph,pm]=form.pausaIni.split(":").map(Number);
              const [fh,fm]=form.pausaFin.split(":").map(Number);
              const mins=(fh*60+fm)-(ph*60+pm);
              return mins>0?<div style={{color:"#f59e0b",fontSize:12,marginTop:4,textAlign:"center"}}>⏸ {mins} min de pausa</div>:<div style={{color:"#ef4444",fontSize:11,marginTop:4}}>La hora de fin debe ser posterior al inicio</div>;
            })()}
          </div>
          {form.entrada&&form.salida&&(
            <div style={{background:"#14b8a615",border:"1px solid #14b8a630",borderRadius:8,padding:"10px 14px",marginBottom:4}}>
              <div style={{display:"flex",justifyContent:"space-between",color:"#94a3b8",fontSize:12}}>
                <span>Horas brutas:</span>
                <span style={{fontWeight:700,color:"#f1f3f9"}}>{(()=>{const[eh,em]=form.entrada.split(":").map(Number);const[sh,sm]=form.salida.split(":").map(Number);const b=(sh*60+sm)-(eh*60+em);if(b<=0)return"—";return`${Math.floor(b/60)}h ${(b%60).toString().padStart(2,"0")}m`;})()}</span>
              </div>
              {form.pausaIni&&form.pausaFin&&(()=>{const mins=calcPausaMins(form.pausaIni,form.pausaFin);return mins>0?<div style={{display:"flex",justifyContent:"space-between",color:"#94a3b8",fontSize:12,marginTop:4}}><span>Pausa:</span><span style={{color:"#f59e0b",fontWeight:700}}>-{mins} min ({form.pausaIni} - {form.pausaFin})</span></div>:null;})()}
              <div style={{display:"flex",justifyContent:"space-between",color:"#94a3b8",fontSize:12,marginTop:4}}>
                <span>Horas netas:</span>
                <span style={{fontWeight:800,color:"#14b8a6",fontSize:14}}>{calcHorasNetas(form.entrada,form.salida,form.pausaIni,form.pausaFin)||"Hora de salida anterior a entrada"}</span>
              </div>
            </div>
          )}
          <Field label="Notas (opcional)"><Textarea value={form.notas} onChange={f("notas")} placeholder="Ej: Trabajo en remoto, salida anticipada, festivo recuperado..."/></Field>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={()=>setModal(null)} style={btnOutline}>Cancelar</button>
            <button onClick={guardar} style={btnPrimary}>{modal.modo==="nuevo"?"Guardar":"Actualizar"}</button>
          </div>
        </Modal>
      )}

      {/* Modal exportar PDF */}
      {modalExport&&(
        <Modal title="Exportar registro de jornada" onClose={()=>setModalExport(false)}>
          <div style={{background:"#0ea5e915",border:"1px solid #0ea5e930",borderRadius:8,padding:"9px 12px",marginBottom:12,color:"#0ea5e9",fontSize:12}}>
            El PDF incluirá logo de empresa, datos del trabajador, tabla de fichajes con pausas y totales, y espacio para firmas.
          </div>
          {(userActual.rol==="manager"||userActual.rol==="admin")&&(
            <Field label="Trabajador">
              <select value={expForm.userId} onChange={e=>setExpForm(p=>({...p,userId:parseInt(e.target.value)}))} style={{...inputStyle}}>
                {usuariosExport.map(u=><option key={u.id} value={u.id}>{u.nombre} — {ROLES_LABEL[u.rol]}</option>)}
              </select>
            </Field>
          )}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:11}}>
            <Field label="Desde"><Input type="date" value={expForm.fechaIni} onChange={ef("fechaIni")}/></Field>
            <Field label="Hasta"><Input type="date" value={expForm.fechaFin} onChange={ef("fechaFin")}/></Field>
          </div>
          <div style={{background:"#2a3550",borderRadius:10,padding:"12px 14px",marginBottom:4}}>
            <div style={{color:"#f59e0b",fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:8}}>Datos del trabajador para el PDF</div>
            <Field label="Nombre completo *"><Input value={expForm.nombreCompleto} onChange={ef("nombreCompleto")} placeholder="Nombre y apellidos completos"/></Field>
            <Field label="DNI / NIE *"><Input value={expForm.dni} onChange={ef("dni")} placeholder="12345678A"/></Field>
          </div>
          <div style={{display:"flex",gap:9,justifyContent:"flex-end",marginTop:8}}>
            <button onClick={()=>setModalExport(false)} style={btnOutline}>Cancelar</button>
            <button onClick={exportarPDF} style={{background:"#f59e0b",border:"none",borderRadius:9,padding:"10px 20px",color:"#0a0f1a",fontWeight:800,cursor:"pointer",fontSize:14,display:"flex",alignItems:"center",gap:6}}>
              <Icon name="parts" size={14}/>Generar PDF
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
};
// ─── FIN FICHAJE ─────────────────────────────────────────────────────────────

