const FichaPublicaMaquina = ({ codigo, data, cargando }) => {
  let found=null;
  (data?.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ if(m.codigo===codigo) found={m,cliente:c}; }));
  const m=found?.m, cliente=found?.cliente;
  const avisosM = m ? (data.avisos||[]).filter(a=>parseInt(a.clienteId)===cliente.id && parseInt(a.maquinaId)===m.id) : [];
  const partesM = m ? (data.partes||[]).filter(p=>parseInt(p.clienteDirectoId)===cliente.id && parseInt(p.maquinaId)===m.id) : [];
  const historial = m ? [
    ...avisosM.map(a=>({tipo:"Aviso", fecha:a.fechaAviso, titulo:a.titulo, estado:a.estado})),
    ...partesM.map(p=>({tipo:"Parte", fecha:p.fecha, titulo:p.descripcion||p.numeroParte, estado:p.estado||""})),
  ].sort((a,b)=>new Date(b.fecha)-new Date(a.fecha)) : [];
  const [pdfMaquina,setPdfMaquina]=useState(null); // { url, nombre, blob } — vista previa del PDF de la máquina
  const cerrarPdfMaquina=()=>{ if(pdfMaquina) URL.revokeObjectURL(pdfMaquina.url); setPdfMaquina(null); };
  const compartirPdfMaquina=async()=>{
    if(!pdfMaquina) return;
    try{
      const archivo=new File([pdfMaquina.blob],pdfMaquina.nombre.replace(/[^\w\sñÑáéíóúÁÉÍÓÚ-]/g,"")+".pdf",{type:"application/pdf"});
      if(navigator.canShare&&navigator.canShare({files:[archivo]})){
        await navigator.share({files:[archivo],title:pdfMaquina.nombre});
      }else if(navigator.share){
        await navigator.share({title:pdfMaquina.nombre,url:pdfMaquina.url});
      }else{
        alert("Tu navegador no permite compartir directamente. Usa el botón Imprimir o descarga el PDF.");
      }
    }catch(e){ /* el usuario cerró el panel de compartir */ }
  };
  const generarPDFMaquina = () => {
    if(!m) return;
    const doc = new jsPDF({ orientation:"portrait", unit:"mm", format:"a4" });
    const W=210; const mg=18;
    const dibujarHeader = () => {
      doc.setFillColor(15,23,42); doc.rect(0,0,W,34,"F");
      doc.setFillColor(245,158,11); doc.rect(0,32,W,2.5,"F");
      try { doc.addImage(LOGO_CIRCULO, "JPEG", mg, 3, 26, 26); } catch(e) {}
      doc.setTextColor(255,255,255); doc.setFontSize(13); doc.setFont("helvetica","bold");
      doc.text("EUROPEA DE MAQUINARIA PMM SL",mg+30,12);
      doc.setFontSize(7); doc.setFont("helvetica","normal"); doc.setTextColor(190,200,220);
      doc.text("Carrer Mas del Jutge 33  ·  46900 Torrent (Valencia)  ·  CIF: B98527583",mg+30,18);
      doc.text("europeademaquinaria.com  ·  info@europeademaquinaria.com  ·  Tel: 961550707",mg+30,24);
      doc.setTextColor(245,158,11); doc.setFontSize(14); doc.setFont("helvetica","bold");
      doc.text("FICHA DE MÁQUINA",W-mg,13,{align:"right"});
      doc.setTextColor(200,210,230); doc.setFontSize(8.5); doc.setFont("helvetica","normal");
      doc.text(m.codigo||"",W-mg,21,{align:"right"});
      doc.text("Fecha: "+fmtFecha(today()),W-mg,27,{align:"right"});
      doc.setFillColor(255,255,255); doc.rect(0,34,W,264,"F");
    };
    dibujarHeader();
    let y=42;
    const box=(titulo,filas,yStart)=>{
      doc.setFillColor(230,235,245); doc.roundedRect(mg,yStart,W-mg*2,7,1,1,"F");
      doc.setDrawColor(180,190,210); doc.roundedRect(mg,yStart,W-mg*2,7,1,1,"S");
      doc.setDrawColor(255,255,255);
      doc.setTextColor(40,60,110); doc.setFontSize(8); doc.setFont("helvetica","bold");
      doc.text(titulo.toUpperCase(),mg+4,yStart+5);
      let fy=yStart+13;
      filas.forEach(([l,v])=>{
        if(!v&&v!==0) return;
        doc.setTextColor(100,115,145); doc.setFontSize(7.5); doc.setFont("helvetica","normal");
        doc.text(l+":",mg+4,fy);
        doc.setTextColor(25,35,60); doc.setFontSize(9); doc.setFont("helvetica","bold");
        const lines=doc.splitTextToSize(String(v),W-mg*2-52);
        doc.text(lines,mg+52,fy);
        fy+=Math.max(lines.length*5.5,6.5);
      });
      return fy+4;
    };
    const asegurarEspacio = (necesario) => {
      if (y+necesario > 268) { doc.addPage(); dibujarHeader(); y=42; }
    };
    const tablaSeccion = (titulo, columnas, filas) => {
      asegurarEspacio(20);
      doc.setFillColor(230,235,245); doc.roundedRect(mg,y,W-mg*2,7,1,1,"F");
      doc.setDrawColor(180,190,210); doc.roundedRect(mg,y,W-mg*2,7,1,1,"S");
      doc.setDrawColor(255,255,255);
      doc.setTextColor(40,60,110); doc.setFontSize(8); doc.setFont("helvetica","bold");
      doc.text(titulo.toUpperCase(),mg+4,y+5); y+=11;
      doc.setFillColor(40,60,110); doc.rect(mg,y,W-mg*2,6,"F");
      let cx=mg;
      doc.setTextColor(255,255,255); doc.setFontSize(7.5); doc.setFont("helvetica","bold");
      columnas.forEach(col=>{ doc.text(col.label,cx+(col.align==="right"?col.w-3:3),y+4.5,{align:col.align==="right"?"right":"left"}); cx+=col.w; });
      y+=7;
      filas.forEach((fila,j)=>{
        asegurarEspacio(8);
        const bgClr = j%2===0 ? [248,250,255] : [255,255,255];
        doc.setFillColor(...bgClr); doc.rect(mg,y-1,W-mg*2,7,"F");
        doc.setTextColor(25,35,70); doc.setFontSize(8.5); doc.setFont("helvetica","normal");
        let cx2=mg;
        columnas.forEach((col,k)=>{
          doc.text(String(fila[k]??"—"),cx2+(col.align==="right"?col.w-3:3),y+4,{align:col.align==="right"?"right":"left"});
          cx2+=col.w;
        });
        y+=7;
      });
      y+=5;
    };
    if(m.foto){
      try {
        const fotoW=60, fotoH=45;
        doc.addImage(m.foto,mg,y,fotoW,fotoH);
        doc.setDrawColor(200,205,220); doc.roundedRect(mg,y,fotoW,fotoH,1,1,"S");
        y+=fotoH+6;
      } catch(e) {}
    }
    y=box("Datos de la máquina",[
      ["Código",m.codigo||"—"],
      ["Nombre",m.nombre||"—"],
      ["Marca",m.marca||"—"],
      ["Modelo",m.modelo||"—"],
      ["Nº serie / matrícula",m.serie||"—"],
      ["Año",m.anyo||"—"],
    ],y);
    asegurarEspacio(20);
    y=box("Cliente",[
      ["Empresa",cliente.nombreEmpresa||"—"],
      ["CIF / DNI",cliente.cif||"—"],
      ["Localidad",cliente.localidad||"—"],
    ],y);
    if(m.notas?.trim()){
      asegurarEspacio(20);
      y=box("Notas",[["Notas",m.notas]],y);
    }
    if(historial.length>0){
      y+=2;
      tablaSeccion("Historial de intervenciones ("+historial.length+")",
        [{label:"FECHA",w:26},{label:"TIPO",w:24},{label:"DESCRIPCIÓN",w:94},{label:"ESTADO",w:30}],
        historial.map(h=>[h.fecha?fmtFecha(h.fecha):"—",h.tipo,h.titulo||"—",h.estado||"—"])
      );
    }
    const totalPaginas = doc.getNumberOfPages();
    for(let pg=1; pg<=totalPaginas; pg++){
      doc.setPage(pg);
      doc.setFillColor(245,158,11); doc.rect(0,281,W,1.5,"F");
      doc.setFillColor(15,23,42); doc.rect(0,282.5,W,14.5,"F");
      doc.setTextColor(190,200,220); doc.setFontSize(7); doc.setFont("helvetica","normal");
      doc.text("Europea de Maquinaria PMM SL  ·  CIF B98527583  ·  europeademaquinaria.com",W/2,291,{align:"center"});
      if(totalPaginas>1){ doc.setTextColor(190,200,220); doc.text("Página "+pg+"/"+totalPaginas,W-mg,291,{align:"right"}); }
    }
    try {
      const dataUri = doc.output("datauristring");
      const byteString = atob(dataUri.split(",")[1]);
      const bytes = new Uint8Array(byteString.length);
      for (let i=0;i<byteString.length;i++) bytes[i]=byteString.charCodeAt(i);
      const blob = new Blob([bytes], {type:"application/pdf"});
      if(pdfMaquina) URL.revokeObjectURL(pdfMaquina.url);
      const url = URL.createObjectURL(blob);
      setPdfMaquina({ url, nombre: "Máquina "+(m.codigo||""), blob });
    } catch(e) { alert("No se pudo generar el PDF de la máquina."); }
  };
  const cerrarFicha = () => { try{ window.location.href = window.location.origin + window.location.pathname; }catch(e){ window.location.search=""; } };
  return (
    <div style={{minHeight:"100vh",background:"#0d1117",color:"#f1f3f9",fontFamily:"Arial,sans-serif",display:"flex",flexDirection:"column",alignItems:"center",padding:"0 0 30px"}}>
      <div style={{width:"100%",background:"#151b2a",borderBottom:"2px solid #0ea5e933",padding:"calc(16px + env(safe-area-inset-top, 0px)) 16px 16px",textAlign:"center",position:"relative"}}>
        <button onClick={cerrarFicha} aria-label="Cerrar" style={{position:"absolute",top:"calc(10px + env(safe-area-inset-top, 0px))",right:12,background:"#2a3550",border:"none",borderRadius:8,padding:7,color:"#f1f3f9",cursor:"pointer",display:"flex"}}><Icon name="close" size={16}/></button>
        <div style={{fontSize:10,color:"#0ea5e9",letterSpacing:2,textTransform:"uppercase",fontWeight:700,marginBottom:6}}>Europea de Maquinaria PMM SL</div>
        <div style={{fontSize:13,color:"#6b7a99"}}>Ficha de máquina</div>
        {m && (
          <button onClick={generarPDFMaquina} style={{marginTop:10,background:"#0ea5e9",color:"#fff",border:"none",borderRadius:8,padding:"8px 14px",fontWeight:700,fontSize:12,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6}}>
            <Icon name="print" size={13}/>Generar PDF
          </button>
        )}
      </div>
      <div style={{width:"100%",maxWidth:420,padding:"20px 16px"}}>
        {!m ? (
          <div style={{textAlign:"center",color:"#6b7a99",padding:"40px 10px"}}>
            {cargando ? "Cargando máquina..." : (
              <>
                <div style={{fontSize:36,marginBottom:10}}>❓</div>
                <div style={{fontWeight:700,color:"#f1f3f9",marginBottom:4}}>Máquina no encontrada</div>
                <div style={{fontSize:13}}>No existe ninguna máquina con el código "{codigo}".</div>
              </>
            )}
          </div>
        ) : (
          <>
            {m.foto && <img src={m.foto} alt={m.nombre} style={{width:"100%",maxHeight:220,objectFit:"cover",borderRadius:12,border:"1px solid #2a3550",marginBottom:14}}/>}
            <div style={{textAlign:"center",marginBottom:16}}>
              <div style={{fontSize:22,fontWeight:900,letterSpacing:2,color:"#0ea5e9",fontFamily:"monospace"}}>{m.codigo}</div>
              <div style={{fontSize:16,fontWeight:700,marginTop:4}}>{m.nombre||`${m.marca||""} ${m.modelo||""}`}</div>
              <div style={{fontSize:12,color:"#6b7a99",marginTop:2}}>Cliente: {cliente.nombreEmpresa}</div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#6b7a99",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Matrícula / Serie</div>
                <div style={{fontSize:16,fontWeight:800}}>{m.serie||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#6b7a99",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Año</div>
                <div style={{fontSize:16,fontWeight:800}}>{m.anyo||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#6b7a99",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Marca</div>
                <div style={{fontSize:14,fontWeight:700,color:"#9aa3b8"}}>{m.marca||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#6b7a99",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Modelo</div>
                <div style={{fontSize:14,fontWeight:700,color:"#9aa3b8"}}>{m.modelo||"—"}</div>
              </div>
            </div>
            {m.notas && <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px",fontSize:13,color:"#9aa3b8",lineHeight:1.6,marginBottom:12}}>{m.notas}</div>}
            <div style={{fontSize:11,fontWeight:700,color:"#6b7a99",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>Historial de intervenciones ({historial.length})</div>
            <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,overflow:"hidden"}}>
              {historial.length===0 && <div style={{padding:"18px",textAlign:"center",color:"#6b7a99",fontSize:12}}>Sin avisos ni partes registrados</div>}
              {historial.map((h,i)=>(
                <div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"10px 14px",borderTop:i?"1px solid #1a2236":"none"}}>
                  <span style={{background:h.tipo==="Aviso"?"#f59e0b20":"#3b82f620",color:h.tipo==="Aviso"?"#f59e0b":"#3b82f6",border:"1px solid "+(h.tipo==="Aviso"?"#f59e0b44":"#3b82f644"),borderRadius:6,padding:"2px 7px",fontSize:9,fontWeight:800}}>{h.tipo}</span>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{h.titulo||"—"}</div>
                    <div style={{color:"#6b7a99",fontSize:10}}>{h.fecha} {h.estado&&("· "+h.estado)}</div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
      <div style={{color:"#3b4460",fontSize:10,marginTop:10}}>Europea de Maquinaria PMM SL</div>
      {pdfMaquina && (
        <div style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.75)",zIndex:1200,display:"flex",flexDirection:"column"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px",paddingTop:"calc(12px + env(safe-area-inset-top, 0px))",background:"#151b2a",borderBottom:"1px solid #2a3550",flexShrink:0,gap:8,flexWrap:"wrap"}}>
            <span style={{color:"#f1f3f9",fontWeight:700,fontSize:14,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",minWidth:0,flex:"1 1 120px"}}>{pdfMaquina.nombre} (vista previa)</span>
            <div style={{display:"flex",gap:8,flexShrink:0}}>
              <button onClick={()=>{ const ifr=document.getElementById("pdfMaquinaFrame"); try{ ifr.contentWindow.focus(); ifr.contentWindow.print(); }catch(e){} }} style={{background:"#0ea5e9",color:"#fff",border:"none",borderRadius:8,padding:"8px 12px",fontWeight:700,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
                <Icon name="print" size={14}/>Imprimir
              </button>
              <button onClick={compartirPdfMaquina} style={{background:"#10b981",color:"#fff",border:"none",borderRadius:8,padding:"8px 12px",fontWeight:700,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
                <Icon name="share" size={14}/>Compartir
              </button>
              <button onClick={cerrarPdfMaquina} style={{background:"#2a3550",border:"none",borderRadius:8,padding:"8px 10px",color:"#f1f3f9",cursor:"pointer",display:"flex",alignItems:"center"}}>
                <Icon name="close" size={16}/>
              </button>
            </div>
          </div>
          <iframe id="pdfMaquinaFrame" src={pdfMaquina.url+"#view=FitH"} title="Vista previa de la ficha de la máquina" style={{flex:1,width:"100%",border:"none",background:"#fff"}}/>
        </div>
      )}
    </div>
  );
};

export default function App() {
  const [data,setData]=useState(()=>{
    try {
      const saved = localStorage.getItem("em_data");
      if(saved){
        const parsed = JSON.parse(saved);
        // Merge: use saved data but fill in any new keys from initialData
        return {
          ...initialData,
          ...parsed,
          // Always merge new initialData keys that don't exist in saved
          smtp: parsed.smtp || initialData.smtp,
          fichajes: parsed.fichajes || initialData.fichajes,
        };
      }
    } catch(e){}
    return initialData;
  });
  const [syncStatus,setSyncStatus]=useState("cargando"); // cargando | ok | guardando | error | offline
  const lastSyncedRef = useRef(null); // JSON de los datos que sabemos están en el servidor
  const dataRef = useRef(data);
  const saveTimerRef = useRef(null);
  useEffect(()=>{ dataRef.current = data; },[data]);

  // Carga inicial desde el servidor: si hay datos remotos, son la fuente de verdad
  // para que todos los usuarios vean lo mismo. Si el servidor está vacío (primera
  // vez), sembramos con lo que tengamos en local (defaults o datos previos).
  useEffect(()=>{
    let cancelled=false;
    (async ()=>{
      try{
        const res = await apiGetData();
        if(cancelled) return;
        if(res.data){
          // lastSyncedRef guarda lo que YA está en el servidor (sin códigos rellenados);
          // si backfillCodigosMaquina añade códigos nuevos, el efecto de autoguardado
          // detectará la diferencia y los subirá automáticamente.
          lastSyncedRef.current = JSON.stringify(res.data);
          setData(backfillConsumiblesClave(backfillCodigosMaquina(res.data)));
        } else {
          try { await apiSaveData(dataRef.current); lastSyncedRef.current = JSON.stringify(dataRef.current); } catch(e){}
        }
        setSyncStatus("ok");
      }catch(e){
        setSyncStatus("offline"); // sin conexión al servidor: seguimos con la copia local
      }
    })();
    return ()=>{ cancelled=true; };
  },[]);

  // Persist ALL data to localStorage on every change (caché local / modo offline)
  useEffect(()=>{
    try { localStorage.setItem("em_data", JSON.stringify(data)); } catch(e){}
  },[data]);

  // Guardar en el servidor cuando cambian los datos (con pequeño debounce)
  useEffect(()=>{
    const json = JSON.stringify(data);
    if(json === lastSyncedRef.current) return;
    setSyncStatus("guardando");
    if(saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(()=>{
      apiSaveData(data)
        .then(()=>{ lastSyncedRef.current = json; setSyncStatus("ok"); })
        .catch(()=>setSyncStatus("error"));
    }, 1200);
    return ()=>clearTimeout(saveTimerRef.current);
  },[data]);

  // Pull periódico para ver cambios hechos por otros usuarios (solo si no tenemos
  // cambios locales propios pendientes de guardar, para no pisarlos)
  useEffect(()=>{
    const pull = async ()=>{
      try{
        const res = await apiGetData();
        if(res.data){
          const remoteJson = JSON.stringify(res.data);
          const localJson = JSON.stringify(dataRef.current);
          if(remoteJson !== localJson && localJson === lastSyncedRef.current){
            lastSyncedRef.current = remoteJson;
            setData(res.data);
          }
        }
        setSyncStatus(s => s==="offline" ? "ok" : s);
      }catch(e){
        setSyncStatus("offline");
      }
    };
    const interval = setInterval(pull, 20000);
    window.addEventListener("focus", pull);
    return ()=>{ clearInterval(interval); window.removeEventListener("focus", pull); };
  },[]);

  const [articuloPublico]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("articulo"); } catch(e) { return null; }
  });
  const [maquinaPublica]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("maquina"); } catch(e) { return null; }
  });
  const [user,setUser]=useState(null);
  const [active,setActive]=useState("asistencia");
  const [notifOpen,setNotifOpen]=useState(false);
  const [menuOpen,setMenuOpen]=useState(false); // sidebar móvil drawer
  const [cuentaOpen,setCuentaOpen]=useState(false); // modal "Mi cuenta"
  const [docFiltro,setDocFiltro]=useState(null); // filtro pendiente al entrar en Documentación desde la ficha de una máquina
  const irADocMaquina=filtro=>{setDocFiltro(filtro);setActive("documentacion");};
  const notifRef=useRef(null);
  const [isMobile,setIsMobile]=useState(()=>window.innerWidth<768);
  const [isTablet,setIsTablet]=useState(()=>window.innerWidth>=768&&window.innerWidth<1024);
  useEffect(()=>{
    const h=()=>{ setIsMobile(window.innerWidth<768); setIsTablet(window.innerWidth>=768&&window.innerWidth<1024); };
    window.addEventListener("resize",h); return()=>window.removeEventListener("resize",h);
  },[]);
  useEffect(()=>{
    const id = "em-responsive";
    if(document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    const css = [
      "*, *::before, *::after { box-sizing: border-box !important; }",
      "html, body { overflow-x: hidden !important; max-width: 100vw !important; }",
      "img, video, canvas, svg { max-width: 100% !important; }",
      "@media (max-width: 767px) {",
      "  .ficha-grid { grid-template-columns: 1fr !important; }",
      "  input, select, textarea { max-width: 100% !important; font-size: 16px !important; }",
      "}"
    ].join("\n");
    style.textContent = css;
    document.head.appendChild(style);
    return () => { const el = document.getElementById(id); if(el) el.remove(); };
  }, []);
  useEffect(()=>{
    if(!user)return;
    const key=`rd_${user.id}_${today()}`;
    if(sessionStorage.getItem(key))return;
    sessionStorage.setItem(key,"1");
    const act=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado");
    if(act.length===0)return;
    const resumen=act.slice(0,5).map(a=>`· ${a.titulo} (${diasDesde(a.fechaAviso)} días)`).join("\n");
    const n=crearNotif(user.id,"diario","📋 Resumen diario — "+today(),`${act.length} avisos activos:\n${resumen}`);
    setData(d=>({...d,notificaciones:{...d.notificaciones,[user.id]:[n,...(d.notificaciones[user.id]||[])]}}));
  },[user]);
  const [avisoAAbrir,setAvisoAAbrir]=useState(null);
  const irAAviso=id=>{setAvisoAAbrir(id);setActive("asistencia");};
  const [clienteAAbrir,setClienteAAbrir]=useState(null);
  const irACliente=id=>{setClienteAAbrir(id);setActive("clientes");};
  const [parteAAbrir,setParteAAbrir]=useState(null);
  const irAParte=id=>{setParteAAbrir(id);setActive("partes");};
  const onNuevoAviso=aviso=>{
    setData(d=>{
      const nn={...d.notificaciones};
      const clienteNombre=d.clientes.find(c=>c.id===aviso.clienteId)?.nombreEmpresa||"—";
      d.usuarios.filter(u=>u.activo).forEach(u=>{
        const n=crearNotif(u.id,"nuevo_aviso",
          `🔔 Nuevo aviso: ${aviso.titulo}`,
          `Cliente: ${clienteNombre} · Prioridad: ${aviso.prioridad} · Asignado: ${listaNombres(aviso,"asignados","asignado").join(" y ")||"Sin asignar"}`
        );
        nn[u.id]=[n,...(nn[u.id]||[])];
      });
      return{...d,notificaciones:nn};
    });
  };
  const onPrueba=async()=>{
    const act=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado");
    const n=crearNotif(user.id,"diario","📋 Resumen manual",`${act.length} avisos activos`);
    setData(d=>({...d,notificaciones:{...d.notificaciones,[user.id]:[n,...(d.notificaciones[user.id]||[])]}}));
    const destino=data.smtp?.from||data.smtp?.user;
    if(!destino){alert("Configura y guarda el SMTP antes de enviar la prueba.");return;}
    try{
      await apiSendMail({
        to: destino,
        subject: "Prueba SMTP — Europea de Maquinaria",
        html: "<p>Esto es un email de prueba.</p><p>Avisos activos: <strong>"+act.length+"</strong>.</p><p>Si lo has recibido, el SMTP está bien configurado.</p>",
      });
      alert("Email de prueba enviado a "+destino+".");
    }catch(e){
      alert("No se pudo enviar el email de prueba.\n\n"+e.message);
    }
  };
  if(articuloPublico){
    if(!user)return <Login usuarios={data.usuarios} onLogin={u=>setUser(u)}/>;
    return <FichaPublicaArticulo codigo={articuloPublico} data={data} cargando={syncStatus==="cargando"}/>;
  }
  if(maquinaPublica){
    // Igual que la ficha de artículo: no se muestra ningún dato (ni el nombre del
    // cliente) hasta que la persona que escanea el QR inicia sesión en la app.
    if(!user)return <Login usuarios={data.usuarios} onLogin={u=>setUser(u)}/>;
    return <FichaPublicaMaquina codigo={maquinaPublica} data={data} cargando={syncStatus==="cargando"}/>;
  }
  if(!user)return <Login usuarios={data.usuarios} onLogin={u=>{setUser(u);setActive("asistencia");}}/>;
  const addNotif=(userId,tipo,titulo,mensaje)=>{
    const n=crearNotif(userId,tipo,titulo,mensaje);
    setData(d=>({...d,notificaciones:{...d.notificaciones,[userId]:[n,...(d.notificaciones[userId]||[])]}}));
  };
  const misNotifs=data.notificaciones[user.id]||[];
  const noLeidas=misNotifs.filter(n=>!n.leida).length;
  const avisosActivos=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado").length;
  // El badge de "Avisos" en la nav debe reflejar solo los avisos activos: antes se le sumaba
  // también el recuento de "reparaciones" (un dato antiguo que no se gestiona desde ninguna
  // pantalla), lo que hacía que con p.ej. 2 avisos activos el número mostrado fuera 4.
  const asistenciaActiva=avisosActivos;
  const leerN=id=>setData(d=>({...d,notificaciones:{...d.notificaciones,[user.id]:(d.notificaciones[user.id]||[]).map(n=>n.id===id?{...n,leida:true}:n)}}));
  const leerT=()=>setData(d=>({...d,notificaciones:{...d.notificaciones,[user.id]:(d.notificaciones[user.id]||[]).map(n=>({...n,leida:true}))}}));
  const misTareasPend=data.tareas.filter(t=>t.asignadoId===user.id&&t.estado!=="Completada").length;
  const navV=NAV_ITEMS.filter(n=>puedeVer(user.rol,n.id));
  const bottomNav = navV.slice(0,4);
  const moreNav   = navV.slice(4);
  const navBadge = id => {
    if(id==="asistencia"&&asistenciaActiva>0) return asistenciaActiva;
    if(id==="tareas"&&misTareasPend>0) return misTareasPend;
    return null;
  };
  const handleNav = id => { setActive(id); setMenuOpen(false); };
  const Topbar = () => (
    <div style={{height:isMobile?"calc(52px + env(safe-area-inset-top))":48,background:"#0a0f1a",borderBottom:"1px solid #1a2236",display:"flex",alignItems:"center",justifyContent:"space-between",padding:isMobile?"env(safe-area-inset-top) 14px 0":"0 20px",flexShrink:0,position:"relative",zIndex:10}}>
      {isMobile?(
        <>
          {/* Logo móvil */}
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <img src={LOGO_URL} style={{width:28,height:28,borderRadius:7,objectFit:"contain"}} alt="EM"/>
            <div style={{fontWeight:900,fontSize:12,color:"#f1f3f9",letterSpacing:".3px"}}>EUROPEA</div>
          </div>
          {/* Titulo módulo activo */}
          <div style={{position:"absolute",left:"50%",transform:"translateX(-50%)",color:"#f1f3f9",fontWeight:700,fontSize:14}}>
            {navV.find(n=>n.id===active)?.label||""}
          </div>
          {/* Notifs + avatar */}
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <div title={SYNC_LABELS[syncStatus]} style={{width:7,height:7,borderRadius:"50%",background:SYNC_COLORS[syncStatus]}}/>
            <div ref={notifRef} style={{position:"relative"}}>
              <button onClick={()=>setNotifOpen(p=>!p)} style={{background:notifOpen?"#1a2236":"transparent",border:"1px solid "+(notifOpen?"#2a3550":"transparent"),borderRadius:7,padding:"5px 7px",cursor:"pointer",color:noLeidas>0?"#ef4444":"#6b7a99",display:"flex",alignItems:"center",gap:3}}>
                <Icon name="bell" size={16}/>{noLeidas>0&&<span style={{background:"#ef4444",color:"#fff",borderRadius:8,padding:"1px 5px",fontSize:10,fontWeight:800}}>{noLeidas}</span>}
              </button>
              {notifOpen&&<NotifPanel notifs={misNotifs} onLeer={leerN} onLeerTodas={leerT} onClose={()=>setNotifOpen(false)} onIrAlChat={()=>{setActive("chat");setNotifOpen(false);}}/>}
            </div>
            <Avatar u={user} size={28} fontSize={11} onClick={()=>setCuentaOpen(true)}/>
          </div>
        </>
      ):(
        <>
          <div style={{color:"#f1f3f9",fontWeight:700,fontSize:15}}>
            {navV.find(n=>n.id===active)?.label||""}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div title={SYNC_LABELS[syncStatus]} style={{width:7,height:7,borderRadius:"50%",background:SYNC_COLORS[syncStatus]}}/>
          <div ref={notifRef} style={{position:"relative"}}>
            <button onClick={()=>setNotifOpen(p=>!p)} style={{background:notifOpen?"#1a2236":"transparent",border:"1px solid "+(notifOpen?"#2a3550":"transparent"),borderRadius:7,padding:"6px 8px",cursor:"pointer",color:noLeidas>0?"#ef4444":"#6b7a99",display:"flex",alignItems:"center",gap:4}}>
              <Icon name="bell" size={16}/>{noLeidas>0&&<span style={{background:"#ef4444",color:"#fff",borderRadius:8,padding:"1px 5px",fontSize:10,fontWeight:800}}>{noLeidas}</span>}
            </button>
            {notifOpen&&<NotifPanel notifs={misNotifs} onLeer={leerN} onLeerTodas={leerT} onClose={()=>setNotifOpen(false)} onIrAlChat={()=>{setActive("chat");setNotifOpen(false);}}/>}
          </div>
          </div>
        </>
      )}
    </div>
  );
  const Sidebar = () => (
    <aside style={{width:isTablet?60:200,background:"#0a0f1a",borderRight:"1px solid #1a2236",display:"flex",flexDirection:"column",flexShrink:0,transition:"width .2s"}}>
      {/* Logo */}
      <div style={{padding:isTablet?"12px 8px":"14px 13px 11px",borderBottom:"1px solid #1a2236",display:"flex",alignItems:"center",justifyContent:isTablet?"center":"flex-start",gap:8}}>
        <img src={LOGO_URL} style={{width:30,height:30,borderRadius:8,objectFit:"contain",flexShrink:0}} alt="EM"/>
        {!isTablet&&<div><div style={{fontWeight:900,fontSize:11,color:"#f1f3f9",letterSpacing:".4px"}}>EUROPEA</div><div style={{fontSize:9,color:"#6b7a99",letterSpacing:".9px"}}>DE MAQUINARIA</div></div>}
      </div>
      {/* Nav */}
      <nav style={{padding:"7px 5px",flex:1,overflow:"auto"}}>
        {navV.map(n=>{
          const badge=navBadge(n.id);
          return(
            <button key={n.id} onClick={()=>handleNav(n.id)} title={isTablet?n.label:""}
              style={{width:"100%",display:"flex",alignItems:"center",justifyContent:isTablet?"center":"space-between",padding:isTablet?"9px":"7px 9px",borderRadius:7,border:"none",cursor:"pointer",marginBottom:1,background:active===n.id?n.color+"20":"transparent",color:active===n.id?n.color:"#6b7a99",fontWeight:active===n.id?700:400,fontSize:12,position:"relative"}}>
              <span style={{display:"flex",alignItems:"center",gap:isTablet?0:7}}>
                <Icon name={n.icon} size={isTablet?18:14}/>
                {!isTablet&&n.label}
              </span>
              {badge&&!isTablet&&<span style={{background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:9,padding:"1px 6px",fontSize:10,fontWeight:800}}>{badge}</span>}
              {badge&&isTablet&&<span style={{position:"absolute",top:4,right:4,background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800,minWidth:14,textAlign:"center"}}>{badge}</span>}
            </button>
          );
        })}
      </nav>
      {/* Usuario */}
      <div style={{padding:isTablet?"8px 5px":"9px 11px",borderTop:"1px solid #1a2236"}}>
        {isTablet?(
          <button onClick={()=>setUser(null)} title="Cerrar sesión" style={{width:"100%",background:"#1a2236",border:"none",borderRadius:6,padding:"8px",color:"#6b7a99",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}><Icon name="logout" size={14}/></button>
        ):(
          <>
            <div onClick={()=>setCuentaOpen(true)} title="Mi cuenta" style={{display:"flex",alignItems:"center",gap:7,marginBottom:6,cursor:"pointer"}}>
              <Avatar u={user} size={26} fontSize={11}/>
              <div style={{flex:1,minWidth:0}}><div style={{color:"#f1f3f9",fontSize:11,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.nombre}</div><RolBadge rol={user.rol}/></div>
            </div>
            <button onClick={()=>setUser(null)} style={{width:"100%",background:"#1a2236",border:"1px solid #2a3550",borderRadius:6,padding:"6px",color:"#6b7a99",fontSize:11,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:5,fontWeight:600}}><Icon name="logout" size={11}/>Cerrar sesión</button>
            <div style={{marginTop:8,textAlign:"center",color:"#6b7a99",fontSize:10,lineHeight:1.5,letterSpacing:"0.3px"}}>Software por <span style={{color:"#f59e0b",fontWeight:700}}>Raúl Ibars</span><br/>2026 · v1.0</div>
          </>
        )}
      </div>
    </aside>
  );
  const BottomNav = () => (
    <nav style={{position:"fixed",bottom:0,left:0,right:0,height:60,background:"#0a0f1a",borderTop:"1px solid #1a2236",display:"flex",alignItems:"stretch",zIndex:100,paddingBottom:"env(safe-area-inset-bottom)"}}>
      {bottomNav.map(n=>{
        const badge=navBadge(n.id);
        const isActive=active===n.id&&!menuOpen;
        return(
          <button key={n.id} onClick={()=>handleNav(n.id)}
            style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",border:"none",background:"transparent",color:isActive?n.color:"#6b7a99",cursor:"pointer",gap:3,position:"relative",padding:"6px 0"}}>
            <div style={{position:"relative"}}>
              <Icon name={n.icon} size={20}/>
              {badge&&<span style={{position:"absolute",top:-5,right:-7,background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800,minWidth:15,textAlign:"center"}}>{badge}</span>}
            </div>
            <span style={{fontSize:9,fontWeight:isActive?700:400,letterSpacing:".2px"}}>{n.label.split(" ")[0]}</span>
            {isActive&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:28,height:3,borderRadius:"0 0 3px 3px",background:n.color}}/>}
          </button>
        );
      })}
      {/* Botón "Más" para el resto */}
      {moreNav.length>0&&(
        <button onClick={()=>setMenuOpen(p=>!p)}
          style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",border:"none",background:"transparent",color:menuOpen||(moreNav.some(n=>n.id===active))?"#f59e0b":"#6b7a99",cursor:"pointer",gap:3,padding:"6px 0",position:"relative"}}>
          {moreNav.some(n=>n.id===active)&&!menuOpen&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:28,height:3,borderRadius:"0 0 3px 3px",background:"#f59e0b"}}/>}
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(260px,100%),1fr))",gap:2,width:18,height:18}}>
            {[0,1,2,3].map(i=><div key={i} style={{background:menuOpen||(moreNav.some(n=>n.id===active))?"#f59e0b":"#6b7a99",borderRadius:2}}/>)}
          </div>
          <span style={{fontSize:9,fontWeight:700,letterSpacing:".2px"}}>Más</span>
        </button>
      )}
    </nav>
  );
  const MoreDrawer = () => menuOpen&&(
    <>
      <div onClick={()=>setMenuOpen(false)} style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.5)",zIndex:110}}/>
      <div style={{position:"fixed",bottom:60,left:0,right:0,background:"#0a0f1a",borderTop:"1px solid #1a2236",zIndex:120,borderRadius:"16px 16px 0 0",padding:"16px 12px 8px"}}>
        <div style={{width:36,height:4,borderRadius:2,background:"#2a3550",margin:"0 auto 16px"}}/>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(100px,100%),1fr))",gap:8,marginBottom:16}}>
          {moreNav.map(n=>{
            const badge=navBadge(n.id);
            return(
              <button key={n.id} onClick={()=>handleNav(n.id)}
                style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,padding:"10px 4px",borderRadius:10,border:"none",background:active===n.id?n.color+"20":"#151b2a",color:active===n.id?n.color:"#6b7a99",cursor:"pointer",position:"relative"}}>
                <div style={{position:"relative"}}><Icon name={n.icon} size={22}/>{badge&&<span style={{position:"absolute",top:-5,right:-7,background:"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800}}>{badge}</span>}</div>
                <span style={{fontSize:10,fontWeight:active===n.id?700:400,textAlign:"center",lineHeight:1.2}}>{n.label}</span>
              </button>
            );
          })}
        </div>
        {/* Usuario info + logout en el drawer */}
        <div style={{borderTop:"1px solid #1a2236",paddingTop:12,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div onClick={()=>{setCuentaOpen(true);setMenuOpen(false);}} title="Mi cuenta" style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer"}}>
            <Avatar u={user} size={32} fontSize={13}/>
            <div><div style={{color:"#f1f3f9",fontSize:13,fontWeight:700}}>{user.nombre}</div><RolBadge rol={user.rol}/></div>
          </div>
          <button onClick={()=>setUser(null)} style={{background:"#1a2236",border:"1px solid #2a3550",borderRadius:8,padding:"7px 12px",color:"#6b7a99",fontSize:12,cursor:"pointer",display:"flex",alignItems:"center",gap:5,fontWeight:600}}><Icon name="logout" size={12}/>Salir</button>
        </div>
      </div>
    </>
  );
  return (
    <div style={{display:"flex",flexDirection:"column",height:"100vh",background:"#0d1117",fontFamily:"'DM Sans','Segoe UI',sans-serif",color:"#f1f3f9",overflow:"hidden",maxWidth:"100vw"}}>
      <Topbar/>
      <div style={{display:"flex",flex:1,overflow:"hidden"}}>
        {!isMobile&&<Sidebar/>}
        <main style={{flex:1,overflow:(active==="chat"&&isMobile)?"hidden":"auto",overflowX:"hidden",padding:isMobile?"14px 10px 76px":"20px 24px",maxWidth:"100%",...((active==="chat"&&isMobile)?{display:"flex",flexDirection:"column",minHeight:0}:{})}}>
          {active==="dashboard"&&<Dashboard data={data} setActive={setActive} userActual={user}/>}
          {active==="asistencia"&&puedeVer(user.rol,"asistencia")&&<AvisosAsistencia data={data} setData={setData} userActual={user} onNuevoAviso={onNuevoAviso} abrirAvisoId={avisoAAbrir} onAbrirAvisoId={()=>setAvisoAAbrir(null)}/>}
          {active==="clientes"&&puedeVer(user.rol,"clientes")&&<Clientes data={data} setData={setData} onIrADocMaquina={irADocMaquina} abrirClienteId={clienteAAbrir} onAbrirClienteId={()=>setClienteAAbrir(null)} userActual={user}/>}
          {active==="maquinas"&&puedeVer(user.rol,"maquinas")&&<Maquinas data={data} setData={setData} userActual={user} irACliente={irACliente} irAAviso={irAAviso} irAParte={irAParte}/>}
          {active==="ventas"&&puedeVer(user.rol,"ventas")&&<Ventas data={data} setData={setData} userActual={user}/>}
          {active==="tareas"&&puedeVer(user.rol,"tareas")&&<Tareas data={data} setData={setData} userActual={user}/>}
          {active==="partes"&&puedeVer(user.rol,"partes")&&<Partes data={data} setData={setData} userActual={user} abrirParteId={parteAAbrir} onAbrirParteId={()=>setParteAAbrir(null)}/>}
          {active==="albaran"&&puedeVer(user.rol,"albaran")&&<Albaran data={data} setData={setData} userActual={user}/>}
          {active==="stock"&&puedeVer(user.rol,"stock")&&<Stock data={data} setData={setData} userActual={user}/>}
          {active==="inventario"&&puedeVer(user.rol,"inventario")&&<Inventario data={data} setData={setData} userActual={user} isMobile={isMobile}/>}
          {active==="documentacion"&&puedeVer(user.rol,"documentacion")&&<Documentacion data={data} setData={setData} filtroInicial={docFiltro} onFiltroConsumido={()=>setDocFiltro(null)}/>}
          {active==="calendario"&&puedeVer(user.rol,"calendario")&&<Calendario data={data} setData={setData} userActual={user} irAAviso={irAAviso}/>}
          {active==="chat"&&puedeVer(user.rol,"chat")&&<Chat data={data} setData={setData} userActual={user} addNotif={addNotif} isMobile={isMobile}/>}
          {active==="fichaje"&&puedeVer(user.rol,"fichaje")&&<Fichaje data={data} setData={setData} userActual={user}/>}
          {active==="usuarios"&&puedeVer(user.rol,"usuarios")&&<Usuarios data={data} setData={setData} userActual={user}/>}
          {active==="ajustes"&&puedeVer(user.rol,"ajustes")&&<Ajustes data={data} setData={setData} onPrueba={onPrueba}/>}
        </main>
      </div>
      {isMobile&&<BottomNav/>}
      {isMobile&&<MoreDrawer/>}
      {cuentaOpen&&<MiCuenta userActual={user} setData={setData} onUpdateUser={setUser} onClose={()=>setCuentaOpen(false)}/>}
    </div>
  );
}
